/* === src/js/custom/qsearch/Place.js === */
/*
 * ogrid.QSearchProcessor.Place
 *
 * Extension class to support geo search for Quick Search classes
 */

ogrid.QSearchProcessor.Place = ogrid.QSearchProcessor.extend({
    //private attributes
    _options:{},

    //customize this RegEx pattern for this processor
    _pattern: '',
    _input:'',

    //public attributes


    //constructor
    init: function(options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },


    //private methods
    _getInitialGeoJson: function() {
        //create a geojson object
        return {
            "type" : "FeatureCollection",
            "features" : [],
            //meta view formatting overrides default from dataset descriptor
            "meta": {
                "view": {
                    "id": "place",
                    "displayName": "Place/Address",
                    "options": {
                        "rendition": {
                            "icon":"marker"
                        }
                    },
                    "columns": [
                        {"id":"name", "displayName":"Name", "dataType":"string", "popup":true, "list":true, "sortOrder":1},
                        {"id":"score", "displayName":"Score", "dataType":"number", "popup":true, "list":true, "sortOrder":2},
                        {"id":"type", "displayName":"Type", "dataType":"string", "popup":true, "list":true, "sortOrder":3},
                        {"id":"lat", "displayName":"Latitude", "dataType":"float", "popup":true, "list":true, "sortOrder":4},
                        {"id":"long", "displayName":"Longitude", "dataType":"float", "popup":true, "list":true, "sortOrder":5}
                    ]
                }
            }
        };
    },

    _isNonPOI: function(addrType) {
        return (addrType === 'PointAddress' ||
            addrType === 'StreetAddress' ||
            addrType === 'BuildingName' ||
            addrType === 'StreetName ' ||
            addrType === 'StreetInt '
        );
    },

    _getAddrTypeScore: function(addrType) {
        if (addrType === 'PointAddress')
            return 5;
        if (addrType === 'BuildingName')
            return 4;
        if (addrType === 'StreetAddress')
            return 3;
        if (addrType === 'StreetName')
            return 2;
        return 1;
    },

    _getLocationSorter: function() {
        var me = this;

        //sort descending
        return function(a, b) {
            if (!a || !b)
                return 0;

            //sort by Addr_type by accuracy
            if (me._getAddrTypeScore(a.feature.attributes.Addr_type) >  me._getAddrTypeScore(b.feature.attributes.Addr_type))
                return -1;
            else  if (me._getAddrTypeScore(a.feature.attributes.Addr_type) <  me._getAddrTypeScore(b.feature.attributes.Addr_type))
                return 1;
            else {
            }

            //sort by score
            if (a.feature.attributes.Score > b.feature.attributes.Score)
                return -1;
            else if (a.feature.attributes.Score < b.feature.attributes.Score)
                return 1;
            else {
                //sort by distance
                if (a.feature.attributes.Distance > b.feature.attributes.Distance)
                    //the smaller distance the better
                    return 1;
                else if (a.feature.attributes.Distance < b.feature.attributes.Distance)
                    return -1;
            }
            return 0;
        };
    },

    _filterAddresses: function(locations) {
        var me = this;

        if (this._options.esriGeocodeFilterUsingShape) {
            var filtered = [];
            var layer = L.geoJson(this._options.esriGeocodeFilterUsingShape);
            $.each(locations, function( i, v ) {
                if (me._isNonPOI(v.feature.attributes.Addr_type)) {
                    //test if in layer
                    var r = leafletPip.pointInLayer(L.latLng(v.feature.geometry.y, v.feature.geometry.x), layer);
                    if (r && (r.length > 0)) {
                        filtered.push(v);
                    }
                } else
                    filtered.push(v);
            });
            return filtered;
        } else
            //return un-changed
            return locations;
    },

    _dumpNames: function(locations) {
        var s='';
        $.each(locations, function( i, v ) {
            s+=v.name + '\n';
        });
        return s;
    },

    _processData: function(data) {
        var o = this._getInitialGeoJson();

        if (data.locations.length >= 1) {
            console.log("Raw results from ArcGIS WorldGeocoder: (" + data.locations.length + ")", data.locations, this._dumpNames(data.locations));
            data.locations = this._filterAddresses(data.locations);

            console.log("Filtered results: ", data.locations, this._dumpNames(data.locations));

            //sort based on score and addr type
            data.locations.sort(this._getLocationSorter());

            console.log("Sorted results: ", data.locations, this._dumpNames(data.locations));

            for (var i in data.locations) {
                //need an Id for interaction between table and map to work
                var id = ogrid.guid();

                if (data.locations[i].feature) {
                    o.features.push( {
                        type:"Feature",
                        id: id,
                        "properties": {
                            "name":  data.locations[i].name,
                            "score": data.locations[i].feature.attributes.Score,
                            "type": data.locations[i].feature.attributes.Type,
                            "lat": data.locations[i].feature.geometry.y,
                            "long": data.locations[i].feature.geometry.x
                        },
                        "geometry": {"type": "Point", "coordinates": [data.locations[i].feature.geometry.x, data.locations[i].feature.geometry.y]}
                    });

                    //for specific address quick searches, return only 1 if most relevant result (1st result) is an address type not POI
                    if ( i=='0' &&
                        data.locations[i].feature.attributes.Addr_type &&
                        this._isNonPOI(data.locations[i].feature.attributes.Addr_type)) {
                        console.log("Addr_type" + data.locations[i].feature.attributes.Addr_type +" - Only Non-POI first result will be returned");
                        break;
                    }
                }



            }

        }
        return o;
    },

    //public methods
    //returns RegEx pattern for supported command
    getPattern: function() {
        return this._pattern;
    },


    exec: function(input, onSuccess, onError) {
        var me = this;

        //force to look within chicago (make configurable later)
        var txt = encodeURI(input);

        //default bounding box to use for esri geoCode search (East IL area)
        var bbox = 'bbox=-89.2700, 37.0000, -87.5000, 42.5000';
        var location = '';

        //overlay with bbox from config, if any
        if (this._options.esriGeocodeBBox) {
            bbox = 'bbox=' + this._options.esriGeocodeBBox;
        }

        if (this._options.esriGeocodeLocation) {
            location = 'location=' + this._options.esriGeocodeLocation;
        }

        $.ajax({
            //use ArcGIS online's geocoder server
            url: 'https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer/find?outSr=4326&outFields=*&maxLocations=' +
                (me._options.esriGeocodeMaxResults || 20) +
                '&' + bbox + '&text=' + txt + '&f=json' + '&' + location,
            type: 'GET',
            async: true,
            timeout: ogrid.Config.service.timeout,
            xhrFields: {
                withCredentials: false
            },
            headers: {
                // Set any custom headers here.
                // If you set any non-simple headers, your server must include these
                // headers in the 'Access-Control-Allow-Headers' response header.
            },
            success: function(data) {
                //data coming back is string
                onSuccess(me._processData(JSON.parse(data)));
            },
            error: function(jqXHR, txtStatus, errorThrown) {
                if (txtStatus === 'timeout') {
                    ogrid.Alert.error('Search has timed out.');
                } else {
                    ogrid.Alert.error( (jqXHR.responseText) ? jqXHR.responseText : txtStatus);
                }
            },
            statusCode: {
                //placeholder
                404: function() {
                    ogrid.Alert.error("ArcGIS Online Geocoder service cannot be reached at this time. Make sure an internet connection is available then try again.");
                }
            }
        });
    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.QSearchProcessor.place = function (options) {
    return new ogrid.QSearchProcessor.Place(options);
};

/* === src/js/custom/qsearch/FlexSearchBuilder.js === */
/*
 * ogrid.FlexSearchBuilder
 *
 * Class for parsing flex quick search that supports searching on all available datasets
 */

ogrid.FlexSearchBuilder = ogrid.Class.extend({
    //private attributes
    _options:{},
    _input: null,
    _rawParamString: '',
    _trigger: '',
    _params: [],
    _highLevelSyntax: /^\s*(\S+)((\s+(\S)+)*)\s*$/i,

    //system field
    _MAX: '$max',

    //public attributes


    //constructor
    init: function(options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },

    //private methods
    _validate: function(input) {
        //var r =  /^(\S)+\s+((("(.+)")|(\S+))|((\S+):(("(.+)")|(\S+))\s*)+)\s*$/i;
        //if (!r.test(input)) {
        //    throw new ogrid.error('Quick Search', 'Invalid quick search input');
        //}
    },

    _parseMain: function(input) {
        var r =  this._highLevelSyntax;
        var matches = r.exec(input);
        if (!matches)
            throw new ogrid.error('Quick Search', 'Invalid quick search input');
        return {trigger: matches[1], params: matches[2].trim() };
    },

    _parseValue: function(value) {
        //pre-condition: value is a single word or quoted string or set of strings
        //quoted string?
        if (/^\s*"(.+)\s*$/i.test(value)) {
            //quotes complete?
            var h = /^\s*"(.+)"\s*$/i.exec(params);
            if (h) {
                return h[1];
            } else
                throw new ogrid.error('Quick Search', 'Missing closing quote');
        } else
            return value;
    },

    _parseKeyValuePairs: function(input, params) {
        //1 or more key-value pairs?
        var r = /\s*(("([^"]+)")|([^\s"]+))\s*:\s*(("([^"]+)")|([^\s"]+))\s*/ig;
        var m = r.exec(input);
        if (m) {
            while (m !== null) {
                params.push({
                    key: this._parseValue(m[3] ? m[3].trim() : m[4].trim()),
                    value: this._parseValue(m[7] ? m[7].trim() : m[5].trim())
                });
                m = r.exec(input);
            }
        } else {
            throw new ogrid.error('Quick Search', 'Invalid quick search input');
        }
    },

    _pushContains: function(filters, value, columns) {
        if (!columns)
            throw new ogrid.error('Quick Search', 'List of columns is missing.');
        var me = this;
        $.each(columns, function(i,v) {
            var o = {};
            //case insensitive contains search
            o[v] = {"$regex":value, "$options": 'i'};
            filters.push( o );
        });
    },

    _momentValueReplacer: function(match, p1) {
        if (p1!==null) {
            if (p1.length > 0)
                //should be a safe eval call due to constrain to work against moment object
                return eval("moment()." + p1 + ".valueOf()"); // jshint ignore:line
            else
            //default moment value containing current epoch
                return moment().valueOf();
        } else {
            return match;
        }
    },

    //public methods


    //mainonly - if true, do not parse params
    parse: function(input, mainonly) {
        this._input = '';
        this._trigger = '';
        this._rawParamString = '';
        this._params = [];

        var o = this._parseMain(input);
        this._trigger = o.trigger;
        this._rawParamString = o.params;

        if (!mainonly)
            this._params = this.parseParams(this._rawParamString);

        this._input = input;
        return this;
    },

    parseParams: function(params) {
        var p = [];
        if (params!=='') {
            //quoted string?
            if (/^\s*"(.+)\s*$/i.test(params)) {
                //quotes complete?
                //var h = /^\s*"(.+)"\s*$/i.exec(params);
                var h = /^\s*"([^"]+)"\s*((\s*(("\$([^"]+)")|(\$[^\s"]+))\s*:\s*(("([^"]+)")|([^\s"]+))\s*)*)$/i.exec(params);
                if (h) {
                    p.push({key: null, value: h[1]});
                    if (h[2]) {
                        //system filters
                        this._parseKeyValuePairs(h[2], p);
                    }
                } else
                    throw new ogrid.error('Quick Search', 'Missing closing quote or invalid filter on system field');
            } else {
                //check if single-bareword
                var r = /^\s*([^\s:"]+)\s*((\s*(("\$([^"]+)")|(\$[^\s"]+))\s*:\s*(("([^"]+)")|([^\s"]+))\s*)*)$/i;
                //if (/^[^\s:]+\s*/i.test(params)) {
                if (r.test(params)) {
                    //p.push({key: null, value: params});
                    var m = /^\s*([^\s:"]+)\s*((\s*(("\$([^"]+)")|(\$[^\s"]+))\s*:\s*(("([^"]+)")|([^\s"]+))\s*)*)$/i.exec(params);
                    if (m) {
                        p.push({key: null, value: m[1]});
                        if (m[2]) {
                            //system filters
                            this._parseKeyValuePairs(m[2], p);
                        }
                    }
                } else {
                    this._parseKeyValuePairs(params, p);
                }
            }
        }
        return p;
    },

    getTrigger: function() {
        return this._trigger;
    },

    //raw key value pair
    getParams: function() {
        if (this._rawParamString && this._rawParamString.trim().length > 0 && this._params.length===0)
            //force a parse
            this._params = this.parseParams(this._rawParamString);
        return this._params;
    },

    //returns Db filter given list of columns
    //now takes baseClientFilter that can be applied when using simple search syntax
    getFilterFromParams: function(params, columns, baseClientFilter) {
        var me = this;
        var f = {};
        $.each(params, function(i, v) {
            if (!me.isSystemColumn(v.key)) {
                if (v.key === null) {
                    //case of simple search syntax <trigger word> "filter"
                    //we're only expecting 1 here
                    var orFilters =  {$or: []};
                    me._pushContains(orFilters.$or, v.value, columns);

                    if (baseClientFilter) {
                        var baseFilter = me.expandBaseFilter(baseClientFilter);

                        //'and' this base filter with orFilters
                        f = {$and: [orFilters, baseFilter]};
                    } else {
                        f = orFilters;
                    }

                    return false; //break
                } else {
                    var o = {};
                    o[v.key] = {"$regex": v.value, "$options": 'i'};
                    if ($.isEmptyObject(f))
                        f = {$and: []};
                    f.$and.push( o );
                }
            }
        });
        if (baseClientFilter) {
            //tack on a base filter for this dataset, if any
            var baseFilter = me.expandBaseFilter(baseClientFilter);

            if (!$.isEmptyObject(f)) {
                if (f.$or) {
                    f = {$and: [f, baseFilter]};
                } else {
                    //$and-ed filters
                    f.$and.push( baseFilter );
                }
            } else {
                f = baseFilter;
            }
        }
        return f;
    },

    //returns actual DB filter
    getFilter: function(columns) {
        return this.getFilterFromParams(this._params, columns);
    },

    //returns limit, defaults to system setting if not specified
    getLimit: function() {
        var me = this;
        var lim = 0;
        $.each(this._params, function(i, v) {
            if (v.key === me._MAX) {
                lim = v.value;
                return false; //break
            }
        });
        return parseInt(lim);
    },

    //quick test function that goes against high-level syntax
    matchesInput: function(input, triggers) {
        var t = false;
        if (this._highLevelSyntax.test(input)) {
            var trigger = this.parse(input, true).getTrigger();

            //matches only if trigger word is on the list
            $.each(triggers, function(i,v){
                //use case-insensitive comparison
                if (trigger.toUpperCase() === v.toUpperCase()) {
                    t = true;
                    return false; //break
                }
            });
        }
        return t;
    },

    isSystemColumn: function(name) {
        //add more later if needed
        return (name === this._MAX);
    },

    //merge options with current
    setOptions: function(options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },

    expandBaseFilter: function(txt) {
        //replace known client filter tokens
        //right now there's only one '@m', which encapsulates moment js expressions
        var r = /@m{((.)*?)}/ig;

        //return filter string
        return JSON.parse(txt.replace(r, this._momentValueReplacer));
    }
});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.flexSearchBuilder = function (options) {
    return new ogrid.FlexSearchBuilder(options);
};

/* === src/js/custom/qsearch/FlexData.js === */
/*
 * ogrid.QSearchProcessor.FlexData
 *
 * Extension class to support any non-LatLong/Place quick searches
 */

ogrid.QSearchProcessor.FlexData = ogrid.QSearchProcessor.extend({
    //private attributes
    _options:{
        datasets: []
    },

    //used by the factory to determine if we need to process a certain input
    //we'll need to build this on the fly
    _matchPattern: null,

    //for parsing, different from the one used by the factory class
    //we may not have to use this
    _parsePattern: null,

    _input: '',
    _flexBuilder: ogrid.flexSearchBuilder(),

    //public attributes


    //constructor
    init: function(options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },


    //private methods
    _processData: function(data) {
        if (data.features.length >= 1) {
            //auto-pop up first element
            //data.features[0].autoPopup = true;
        }
    },

    _getParams: function(input) {
        //this is where we need the FlexQueryBuilder
    },

    //determine dataset based on trigger word or alias
    _getDatasetByTrigger: function(trigger) {
        var ds = null;
        $.each(this._options.datasets, function(i, v) {
            if (v.quickSearch && v.quickSearch.enable) {
                //use case insensitive search
                if (v.quickSearch.triggerWord.toUpperCase() === trigger.toUpperCase() || v.quickSearch.triggerAlias.toUpperCase() === trigger.toUpperCase()) {
                    ds = v;
                    return false; //break
                }
            }
        });
        if (ds === null) {
            throw new ogrid.error('Quick Search', "No matching dataset can be found for trigger '" + trigger + "'");
        }
        return ds;
    },

    _getDatasetByDatasetId: function(dsId) {
        var ds = null;
        $.each(this._options.datasets, function(i, v) {
            if (v.quickSearch && v.quickSearch.enable) {
                if (v.id === dsId) {
                    ds = v;
                    return false; //break
                }
            }
        });
        if (ds === null) {
            throw new ogrid.error('Quick Search', "No matching dataset can be found for id '" + dsId + "'");
        }
        return ds;
    },

    _resolveColumnAliases: function(ds, params) {
        var me = this;

        //replace keys with real field names if shortcut names were used
        //assumption no other fields with the same names are in the DB collection (e.g. what.x1, where.x1)
        $.each(params, function(i, v) {

            if (v.key !== null) {
                //key-value pairs only
                var found = false;

                if (me._flexBuilder.isSystemColumn(v.key)) {
                    found = true;
                } else {
                    //look up from dataset columns
                    $.each(ds.columns, function(j, w) {
                        if (w.quickSearch) {
                            //only for columns available for quicksearch filtering
                            if (v.key === w.id) {
                                found = true;
                                //do nothing, break
                                return false;
                            } else {
                                //match by qualified column name
                                var a = w.id.split('.');
                                if (a[a.length -1] === v.key) {
                                    v.key = w.id;
                                    found = true;
                                    return false;
                                } else {
                                    //do nothing, continue
                                }
                            }
                        }
                    });
                }
                if (!found)
                    throw new ogrid.error('Quick Search', "Invalid column id '" + v.key  + "'");
            }
        });
    },


    _getQuickSearchColumns:function(ds) {
        return $.map(ds.columns, function(v,i){
            if (v.quickSearch) {
                return v.id;
            }
        });
    },


    _getGeoFilterWidget: function() {
        var fakeContainer = $();
        var o =  ogrid.geoFilter(fakeContainer, {
                bounds: ogrid.Config.advancedSearch.geoFilterBoundaries,

                //no additional near refs aside from _map-click
                nearReferences: null,

                //pass the true map object
                map: ogrid.App.map().getMap(),
                geoLocationControl: ogrid.App.map().getGeoLocationControl()
            }
        );
        //this makes it map-extent by default
        o.reset();
        return o;
    },

    _getMapExtentGeoFilter:function() {
        if ( !this._geoFilter ) {
            this._geoFilter = this._getGeoFilterWidget();
        }
        return this._geoFilter.getGeoFilter();
    },

    //public methods
    test: function(input) {
        //dynamically determine pattern based on available datasets
        var triggers = [];

        $.each(this._options.datasets, function(i, v) {
            //only those available for quickSearch
            if (v.quickSearch && v.quickSearch.enable) {
                triggers.push(v.quickSearch.triggerWord);
                if (v.quickSearch.triggerAlias) {
                    //add alias as a valid trigger word too
                    triggers.push(v.quickSearch.triggerAlias);
                }
            }
        });
        return this._flexBuilder.matchesInput(input, triggers);
    },

    validate: function(input) {
        //return this._parsePattern.test(input);
        //we can implement this later, exec validates the input anyway
        return false;
    },


    exec: function(input, onSuccess, onError) {
        var ds = null;
        try {
            //pass true to parse only main tokens to get the trigger
            this._flexBuilder.parse(input, true);
            ds = this._getDatasetByTrigger(this._flexBuilder.getTrigger());

            var params = this._flexBuilder.getParams();
            this._resolveColumnAliases(ds, params);

            //var filter = this._flexBuilder.getFilterFromParams(params, this._getQuickSearchColumns(ds), ds.quickSearch.baseClientFilter);
            /*if ($.isEmptyObject(filter)) {
                //use base client filter for this ds, if any
                if (ds.quickSearch.baseClientFilter) {
                    filter = this._flexBuilder.expandBaseFilter(ds.quickSearch.baseClientFilter);
                }
            }*/

            var request = {
                dataSetId: ds.id,
                filter: this._flexBuilder.getFilterFromParams(params, this._getQuickSearchColumns(ds), ds.quickSearch.baseClientFilter),
                success: onSuccess,
                error: onError
            };

            //max if specified on input, else dstaset default max, else service default max
            request.maxResults = this._flexBuilder.getLimit() || ds.quickSearch.defaultMax ||  ogrid.Config.service.maxresults;
            request.sort = ds.quickSearch.defaultSort || null;

            //if geoSpatial filtering is supported by service, send geoSpatial filters
            if ( ogrid.App.serviceCapabilities && ogrid.App.serviceCapabilities().geoSpatialFiltering ) {
                request.geoFilter = this._getMapExtentGeoFilter();
            }
            ogrid.Search.exec( request, {origin: 'qsearchFlex'});

        } catch (ex) {
            if (ex.message.indexOf('invalid filter')> -1) {
                if (ds)
                    throw new ogrid.error('Quick Search', ds.displayName + ' quick search input is invalid');
                else
                    throw new ogrid.error('Quick Search', 'Quick Search input is invalid');
            } else
                throw ex;
        }
    },

    getFlexSearchBuilder: function() {
        return this._flexBuilder;
    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.QSearchProcessor.flexData = function (options) {
    return new ogrid.QSearchProcessor.FlexData(options);
};

/* === src/js/custom/qsearch/AISearch.js === */
/*
 * ogrid.QSearchProcessor.AISearch
 *
 * Catch-all quick search processor that routes queries to the smart search endpoint.
 * Handles both POI/address lookups (via ArcGIS geocoder server-side) and
 * natural language data queries (via Claude + chicago-data-mcp).
 */

// Phrases that signal the user wants results near their current GPS position.
var _GEO_SELF_RE = /\b(near(?: me| here)|nearby|close to me|by me|around(?: me| here)?|from here|right here|in (?:my (?:neighborhood|area|vicinity|community|part of town|backyard|block|street)|this area)|at my (?:house|home|address)|where i live|near where i live|(?:my )?current location|my location|locally)\b/i;

ogrid.QSearchProcessor.AISearch = ogrid.QSearchProcessor.extend({
    _options: {
        endpoint: null
    },

    init: function(options) {
        if (options) {
            this._options = $.extend(this._options, options);
        }
    },

    // Accepts anything not already claimed by LatLng or FlexData
    test: function(input) {
        return (input && $.trim(input).length > 0);
    },

    exec: function(input, onSuccess, onError) {
        var me = this;
        var trimmed = $.trim(input);

        if (_GEO_SELF_RE.test(trimmed) && navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                function(pos) {
                    me._doSearch(trimmed, {lat: pos.coords.latitude, lon: pos.coords.longitude}, onSuccess, onError);
                },
                function() {
                    onError('Location access is required for this search. Please allow location access and try again.');
                },
                { timeout: 10000, maximumAge: 60000 }
            );
        } else {
            me._doSearch(trimmed, null, onSuccess, onError);
        }
    },

    _doSearch: function(input, currentLocation, onSuccess, onError) {
        var me = this;
        var endpoint = me._options.endpoint || ogrid.Config.service.endpoint;
        var url = endpoint.replace(/\/rest\/?$/, '') + '/rest/search/smart';

        var payload = { query: input };
        try {
            var mapBounds = ogrid.App.map().getMap().getBounds();
            payload.bounds = {
                minLat: mapBounds.getSouth(),
                minLon: mapBounds.getWest(),
                maxLat: mapBounds.getNorth(),
                maxLon: mapBounds.getEast()
            };
        } catch(e) {}

        if (currentLocation) {
            payload.current_location = currentLocation;
            console.log('[AISearch] current_location:', currentLocation);
        }

        $.ajax({
            url: url,
            type: 'POST',
            contentType: 'application/json',
            data: JSON.stringify(payload),
            headers: (function() {
                var token = typeof sessionStorage !== 'undefined' ? sessionStorage.getItem('auth_token') : null;
                return token ? { 'X-AUTH-TOKEN': token } : {};
            }()),
            timeout: 60000,
            success: function(data) {
                if (data && (data.features !== undefined || data.layers !== undefined)) {
                    onSuccess(data);
                } else {
                    onError('Unexpected response format from smart search');
                }
            },
            error: function(xhr, status, err) {
                onError(err || status, {jqXHR: xhr, txtStatus: status, errorThrown: err});
            }
        });
    }
});

ogrid.QSearchProcessor.aiSearch = function(options) {
    return new ogrid.QSearchProcessor.AISearch(options);
};


