/* === src/js/core/Util.js === */
/*
 * Partly from of Leaflet's L.Util - for self-sufficiency in case we switch to another map library in the future
 */

ogrid.Util = {
	// extend an object with properties of one or more other objects
	mixin: function (dest) {
		var i, j, len, src;

		for (j = 1, len = arguments.length; j < len; j++) {
			src = arguments[j];
			for (i in src) {
				dest[i] = src[i];
			}
		}
		return dest;
	},

	// create an object from a given prototype
	create: Object.create || (function () {
		function F() {}
		return function (proto) {
			F.prototype = proto;
			return new F();
		};
	})(),

	// bind a function to be called with a given context
	bind: function (fn, obj) {
		var slice = Array.prototype.slice;

		if (fn.bind) {
			return fn.bind.apply(fn, slice.call(arguments, 1));
		}

		var args = slice.call(arguments, 2);

		return function () {
			return fn.apply(obj, args.length ? args.concat(slice.call(arguments)) : arguments);
		};
	},

	// round a given number to a given precision
	formatNum: function (num, digits) {
		var pow = Math.pow(10, digits || 5);
		return Math.round(num * pow) / pow;
	},

	// trim whitespace from both sides of a string
	trim: function (str) {
		return str.trim ? str.trim() : str.replace(/^\s+|\s+$/g, '');
	},

	// split a string into words
	splitWords: function (str) {
		return ogrid.Util.trim(str).split(/\s+/);
	},

	// set options to an object, inheriting parent's options as well
	setOptions: function (obj, options) {
		if (!obj.hasOwnProperty('options')) {
			obj.options = obj.options ? ogrid.Util.create(obj.options) : {};
		}
		for (var i in options) {
			obj.options[i] = options[i];
		}
		return obj.options;
	},

	// make a URL with GET parameters out of a set of properties/values
	getParamString: function (obj, existingUrl, uppercase) {
		var params = [];
		for (var i in obj) {
			params.push(encodeURIComponent(uppercase ? i.toUpperCase() : i) + '=' + encodeURIComponent(obj[i]));
		}
		return ((!existingUrl || existingUrl.indexOf('?') === -1) ? '?' : '&') + params.join('&');
	},

	isNull: function(v) {
		return ( (typeof(v) === 'undefined') || (v === null) );
	},

	error: function ( name_text, msg_text, data ) {
		var error     = new Error();
		error.name    = name_text;
		error.message = msg_text;

		if ( data ){ error.data = data; }

		return error;
	},

	_s4: function () {
		return (((1 + Math.random()) * 0x10000) | 0).toString(16).substring(1);
	},

	guid: function() {
		return (ogrid.Util._s4() + ogrid.Util._s4() + "-" + ogrid.Util._s4() + "-4" + ogrid.Util._s4().substr(0,3) + "-" + ogrid.Util._s4() + "-" + ogrid.Util._s4() + ogrid.Util._s4() + ogrid.Util._s4()).toLowerCase();
	},

	ajax: function(context, success, options) {
		var opt = options; //default but override for some values
		$.ajax({
			//append relative url
			url: ogrid.Config.service.endpoint + opt.url,
			type: opt.type,
			async: true,
			contentType: 'application/json',
			timeout: ogrid.Config.service.timeout,
			xhrFields: {
				withCredentials: false
			},
			headers: {
				// Set any custom headers here.
				// If you set any non-simple headers, your server must include these
				// headers in the 'Access-Control-Allow-Headers' response header.
			},
			success: function(data) {
				success.call(context, data);
			},
			error: function(jqXHR, txtStatus, errorThrown) {
				if (txtStatus === 'timeout') {
					console.log('Service call has timed out.');
					//ogrid.Alert.error('Search has timed out.');
				} else {
					console.log( (jqXHR.responseText) ? jqXHR.responseText : txtStatus);
					//ogrid.Alert.error( (jqXHR.responseText) ? jqXHR.responseText : txtStatus);
				}
			},
			statusCode: {
				//placeholder
				404: function() {
					console.log("Page not found" );
					//ogrid.Alert.error( "Page not found" );
				}
			}
		});
	},

	getGeoJsonFeatureId: function(feature) {
		if (feature.id) {
			if (feature.id.hasOwnProperty('$oid')) {
				return feature.id.$oid;
			} else {
				return feature.id;
			}
		}
		return null;
	},

	hereDoc: function(f) {
		return f.toString().match(/\/\*\s*([\s\S]*?)\s*\*\//m)[1].replace(/(\/\*[\s\S]*?\*) \//g, '$1/');
	},

	//current current day and time
	now: function() {
		/*Date.prototype.today = function () {
			//mm/dd/yyyy
			return (((this.getMonth()+1) < 10)?"0":"") + (this.getMonth()+1) + "/"  + ((this.getDate() < 10)?"0":"") + this.getDate() + "/"+ this.getFullYear();
		};

		// For the time now
		Date.prototype.timeNow = function () {
			return ((this.getHours() < 10)?"0":"") + this.getHours() +":"+ ((this.getMinutes() < 10)?"0":"") + this.getMinutes() +":"+ ((this.getSeconds() < 10)?"0":"") + this.getSeconds();
		};

		return new Date().today() + " " + new Date().timeNow();*/
		return moment();
	},

	waitForCondition: function(maxTime, fn) {
		var d = $.Deferred();

		//async loop
		var _loop = function (i) {
			setTimeout(function() {
				if (d.state() === 'pending') {
					fn(d);
				}
			}, i * 500);
		};

		var n = (maxTime / 500);
		//max of 5 seconds, we're anticipating some wasted cycles here
		for (var i = 0; i < n; i++) {
			_loop(i);
		}
		return d;
	}
};

// shortcuts for most used utility functions
ogrid.mixin = ogrid.Util.mixin;
ogrid.bind = ogrid.Util.bind;
ogrid.setOptions = ogrid.Util.setOptions;
ogrid.formatNum = ogrid.Util.formatNum;
ogrid.trim = ogrid.Util.trim;
ogrid.splitWords = ogrid.Util.splitWords;
ogrid.isNull = ogrid.Util.isNull;
ogrid.error = ogrid.Util.error;
ogrid.guid = ogrid.Util.guid;
ogrid.ajax = ogrid.Util.ajax;
ogrid.oid = ogrid.Util.getGeoJsonFeatureId;
ogrid.hereDoc = ogrid.Util.hereDoc;
ogrid.now = ogrid.Util.now;
ogrid.waitForCondition = ogrid.Util.waitForCondition;

//more "native" bind implementation
if (!Function.prototype.bind) { // check if native implementation available
	Function.prototype.bind = function(){
		var fn = this, args = Array.prototype.slice.call(arguments),
			object = args.shift();
		return function(){
			return fn.apply(object,
				args.concat(Array.prototype.slice.call(arguments)));
		};
	};
}

/* === src/js/custom/StreetView.js === */
/*
 * Google Street View popup helper.
 *
 * Keeps Street View image construction in one place for query-result features
 * and persistent object markers. The API key is read at render time so
 * environment overrides can provide it after the main bundle loads.
 */
(function() {
    function _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function _cfg() {
        var mapCfg = (ogrid.Config && ogrid.Config.map) || {};
        return mapCfg.googleStreetView || {};
    }

    function _key() {
        var mapCfg = (ogrid.Config && ogrid.Config.map) || {};
        return (mapCfg.googleStreetViewApiKey || ogrid.Config.googleStreetViewApiKey || '').trim();
    }

    function _num(v) {
        var n = parseFloat(v);
        return isNaN(n) ? null : n;
    }

    function _latLon(opts) {
        opts = opts || {};
        var lat = _num(opts.lat != null ? opts.lat : opts.latitude);
        var lon = _num(opts.lon != null ? opts.lon : opts.lng != null ? opts.lng : opts.longitude);
        if (lat == null || lon == null) return null;
        return { lat: lat, lon: lon };
    }

    function _url(lat, lon) {
        var cfg = _cfg();
        var params = [
            'size=' + encodeURIComponent(cfg.size || '320x180'),
            'location=' + encodeURIComponent(lat + ',' + lon),
            'fov=' + encodeURIComponent(cfg.fov || 80),
            'pitch=' + encodeURIComponent(cfg.pitch || 0),
            'radius=' + encodeURIComponent(cfg.radius || 50),
            'source=outdoor',
            'key=' + encodeURIComponent(_key())
        ];
        return 'https://maps.googleapis.com/maps/api/streetview?' + params.join('&');
    }

    function imageHtml(opts) {
        var ll = _latLon(opts);
        if (!ll) return '';

        if (!_key()) {
            return '<div class="ogrid-streetview ogrid-streetview-empty">' +
                   '<i class="fa fa-street-view" aria-hidden="true"></i>' +
                   '<span>Street View needs a Google API key.</span>' +
                   '</div>';
        }

        return '<div class="ogrid-streetview">' +
               '<img src="' + _esc(_url(ll.lat, ll.lon)) + '" alt="Google Street View image" loading="lazy">' +
               '</div>';
    }

    function popupHtml(opts) {
        opts = opts || {};
        var title = opts.title
            ? '<div class="ogrid-streetview-title">' + _esc(opts.title) + '</div>'
            : '';
        var body = opts.body || '';
        return '<div class="ogrid-streetview-popup">' +
               title +
               imageHtml(opts) +
               body +
               '</div>';
    }

    function attachToMarker(marker, opts) {
        if (!marker || !marker.bindPopup) return marker;
        marker.bindPopup('', { maxWidth: 360, className: 'ogrid-streetview-leaflet-popup' });
        marker.on('popupopen', function() {
            marker.setPopupContent(popupHtml(opts || {}));
        });
        return marker;
    }

    function openMarkerPopup(marker) {
        if (marker && marker.openPopup) {
            marker.openPopup();
        }
    }

    ogrid.StreetView = {
        attachToMarker: attachToMarker,
        imageHtml: imageHtml,
        openMarkerPopup: openMarkerPopup,
        popupHtml: popupHtml
    };
}());


/* === src/js/custom/community/CommunityAreaLabels.js === */
/*
 * ogrid.CommunityAreaLabels
 *
 * Clickable Chicago community-area NAME labels on the map. Only the name text is
 * clickable (there is no clickable polygon) — clicking a name opens that area's
 * Community Trends profile. Labels scale with zoom (smaller zoomed out, larger zoomed
 * in), mirroring the CTA/Metra station marker behavior, and are suppressed below a
 * minimum zoom where 77 names would overlap into noise.
 *
 * Shown by default; the map toggle button hides/shows them.
 *
 * Backend: GET /geography/community-areas/boundaries (GeoJSON FeatureCollection).
 */
ogrid.CommunityAreaLabels = ogrid.Class.extend({

    // Below this zoom the whole city is a clump — labels would overlap, so hide them.
    _MIN_ZOOM: 11,

    _map: null,
    _group: null,
    _labels: null,      // [{ marker, center, name, number }]
    _loaded: false,
    _enabled: false,    // whether labels are active
    _onMap: false,      // whether the group is currently added to the map

    init: function(options) {
        this._options = options || {};
        this._map = this._options.map;
        this._labels = [];
        this._map.on('zoomend', $.proxy(this._onZoom, this));
        // Community-area names are always on (zoom-gated); no toggle control.
        this.show();
    },

    _endpoint: function() {
        return (this._options.endpoint || ogrid.Config.service.endpoint).replace(/\/$/, '');
    },

    _authHeaders: function() {
        var token = (typeof sessionStorage !== 'undefined') ? sessionStorage.getItem('auth_token') : null;
        return token ? { 'X-AUTH-TOKEN': token } : {};
    },

    // --- zoom-responsive font sizing ---------------------------------------
    _fontForZoom: function(zoom) {
        if (zoom >= 16) return 19;
        if (zoom >= 15) return 17;
        if (zoom >= 14) return 15;
        if (zoom >= 13) return 13;
        if (zoom >= 12) return 11;
        return 10; // zoom 11 (labels are hidden below _MIN_ZOOM)
    },

    _labelIcon: function(name, zoom) {
        return L.divIcon({
            className: 'ocp-map-label',
            html: '<span class="ocp-label-text" style="font-size:' +
                  this._fontForZoom(zoom) + 'px;">' + name + '</span>',
            iconSize: null
        });
    },

    show: function() {
        var me = this;
        this._enabled = true;
        this._ensureLoaded(function() { me._updateVisibility(); });
    },

    hide: function() {
        this._enabled = false;
        if (this._group && this._onMap) { this._map.removeLayer(this._group); }
        this._onMap = false;
    },

    _onZoom: function() {
        if (this._enabled) { this._updateVisibility(); }
    },

    // Add/remove the label group based on zoom, and rescale visible labels.
    _updateVisibility: function() {
        if (!this._group) { return; }
        var zoom = this._map.getZoom();

        if (zoom < this._MIN_ZOOM) {
            if (this._onMap) { this._map.removeLayer(this._group); this._onMap = false; }
            return;
        }
        if (!this._onMap) { this._group.addTo(this._map); this._onMap = true; }
        this._resizeLabels(zoom);
    },

    _resizeLabels: function(zoom) {
        var me = this;
        this._labels.forEach(function(l) {
            l.marker.setIcon(me._labelIcon(l.name, zoom));
        });
    },

    _ensureLoaded: function(cb) {
        if (this._loaded) { cb(); return; }
        var me = this;
        $.ajax({
            url: this._endpoint() + '/geography/community-areas/boundaries',
            type: 'GET',
            headers: this._authHeaders(),
            success: function(fc) {
                me._build(fc);
                me._loaded = true;
                cb();
            },
            error: function() {
                if (ogrid.Alert && ogrid.Alert.error) {
                    ogrid.Alert.error('Could not load community-area names.');
                }
            }
        });
    },

    _open: function(number) {
        // Switch through the app router so browser history captures the profile.
        if (ogrid.App && ogrid.App.navigateToPage) {
            ogrid.App.navigateToPage('trends', { communityArea: number });
        } else {
            ogrid.communityProfile().show();
            ogrid.communityProfile().load(number);
        }
    },

    _build: function(fc) {
        var me = this;
        this._group = L.layerGroup();
        this._labels = [];
        var zoom = this._map.getZoom();

        (fc && fc.features ? fc.features : []).forEach(function(feature) {
            var number = feature.properties.number;
            var name = feature.properties.name;

            // Centroid via an in-memory GeoJSON layer (never added to the map);
            // we only render the clickable name, not the polygon.
            var center;
            try {
                center = L.geoJSON(feature).getBounds().getCenter();
            } catch (e) {
                return; // skip degenerate geometry
            }

            var marker = L.marker(center, {
                interactive: true,
                keyboard: false,
                icon: me._labelIcon(name, zoom),
                zIndexOffset: 650
            });
            marker.on('click', function() { me._open(number); });
            me._group.addLayer(marker);
            me._labels.push({ marker: marker, center: center, name: name, number: number });
        });
    }
});


/* === src/js/custom/community/CommunityProfile.js === */
/*
 * ogrid.CommunityProfile
 *
 * Community Trends panel: headline ACS indicators + citywide comparison for a single
 * Chicago community area. Rendered into #ogrid-community-profile. Reached two ways —
 * the sidebar "Community Trends" item (with a dropdown selector) and clicking a
 * community-area label on the map (ogrid.communityProfile().load(number)).
 *
 * Backend: GET /geography/community-areas            (selector list)
 *          GET /geography/community-areas/{n}/profile (KPIs + comparison)
 */
ogrid.CommunityProfile = ogrid.Class.extend({

    _container: null,
    _built: false,
    _areasLoaded: false,
    _current: null,

    init: function(options) {
        this._options = options || {};
        this._container = $('#ogrid-community-profile');
        this._charts = [];          // live Chart.js instances (destroyed on reload)
        this._pendingCharts = [];   // chart specs awaiting DOM insertion
        this._chartSeq = 0;         // unique canvas id counter
        this._summarySeq = 0;       // guards async summary responses during area switches
        this._miniMap = null;
    },

    _endpoint: function() {
        return (this._options.endpoint || ogrid.Config.service.endpoint).replace(/\/$/, '');
    },

    _authHeaders: function() {
        var token = (typeof sessionStorage !== 'undefined') ? sessionStorage.getItem('auth_token') : null;
        return token ? { 'X-AUTH-TOKEN': token } : {};
    },

    // Build the static chrome (header + selector) once.
    _build: function() {
        if (this._built) { return; }
        var me = this;
        this._container.html(
            '<div class="ocp-page">' +
              '<div class="ocp-header">' +
                '<div class="ocp-title"><i class="fa fa-bar-chart"></i> Community Trends</div>' +
                '<div class="ocp-area-picker">' +
                  '<label for="ocp-area-select">Community area</label>' +
                  '<select id="ocp-area-select" class="ocp-area-select"></select>' +
                '</div>' +
              '</div>' +
              '<div id="ocp-body" class="ocp-body">' +
                '<div class="ocp-empty">Select a community area to see its profile.</div>' +
              '</div>' +
            '</div>'
        );
        $('#ocp-area-select').on('change', function() {
            var val = $(this).val();
            if (val === 'chicago') { me.load('chicago'); return; }
            var num = parseInt(val, 10);
            if (num) { me.load(num); }
        });
        this._built = true;
        this._loadAreas();
    },

    _loadAreas: function() {
        if (this._areasLoaded) { return; }
        var me = this;
        $.ajax({
            url: this._endpoint() + '/geography/community-areas',
            type: 'GET',
            headers: this._authHeaders(),
            success: function(areas) {
                var $sel = $('#ocp-area-select');
                $sel.empty().append('<option value="">— choose —</option>');
                $sel.append('<option value="chicago">Chicago (Citywide)</option>');
                (areas || []).forEach(function(a) {
                    $sel.append('<option value="' + a.number + '">' + a.name + '</option>');
                });
                me._areasLoaded = true;
                // If a profile was requested before the list arrived, reflect it now.
                if (me._current) { $sel.val(String(me._current)); }
            },
            error: function() {
                $('#ocp-body').html('<div class="ocp-empty">Could not load the community-area list.</div>');
            }
        });
    },

    show: function() {
        this._build();
        this._container.removeClass('hide');
        if (!this._current) { this.load('chicago'); }
    },

    hide: function() {
        this._container.addClass('hide');
    },

    // Load and render the profile for a community area number, or 'chicago' for citywide.
    load: function(number) {
        var me = this;
        this._build();
        this._current = number;
        this._destroyCharts();
        this._destroyMiniMap();
        if (this._areasLoaded) {
            $('#ocp-area-select').val(number === 'chicago' ? 'chicago' : String(number));
        }
        $('#ocp-body').html('<div class="ocp-loading"><i class="fa fa-spinner fa-spin"></i> Loading…</div>');

        var seg = (number === 'chicago') ? 'chicago' : number;
        $.ajax({
            url: this._endpoint() + '/geography/community-areas/' + seg + '/profile',
            type: 'GET',
            headers: this._authHeaders(),
            success: function(data) { me._render(data); },
            error: function() {
                $('#ocp-body').html('<div class="ocp-empty">Could not load this community profile.</div>');
            }
        });
    },

    _render: function(data) {
        if (!data || data.available === false) {
            var msg = (data && data.message) || 'Census data unavailable for this community area.';
            $('#ocp-body').html(
                '<div class="ocp-area-name">' + ((data && data.name) || '') + '</div>' +
                '<div class="ocp-empty">' + msg + '</div>'
            );
            return;
        }

        var meta = (data.number != null)
            ? 'Community Area ' + data.number + ' · ACS ' + data.acs_year + ' (5-yr)'
            : 'ACS ' + data.acs_year + ' (5-yr)';
        var html =
            '<div class="ocp-area-head">' +
              '<div class="ocp-area-name">' + data.name + '</div>' +
              '<div class="ocp-area-meta">' + meta + '</div>' +
            '</div>' +
            this._renderOverview(data) +
            this._renderKpis(data.kpis) +
            this._renderSections(data.sections);

        $('#ocp-body').html(html);
        this._instantiateCharts();
        if (data.number != null) { this._renderBoundaryMap(data.boundary); }
        this._loadSummary(data.number);
    },

    _renderOverview: function(data) {
        var boundaryCard = (data.number != null)
            ? '<div class="ocp-boundary-card">' +
                '<div id="ocp-boundary-map" class="ocp-boundary-map"></div>' +
                '<div class="ocp-boundary-label">Community Area ' + this._esc(data.number) + '</div>' +
              '</div>'
            : '';
        return '<div class="ocp-overview-row">' +
                 '<div class="ocp-summary-card">' +
                   '<div class="ocp-summary-title">About ' + this._esc(data.name) + '</div>' +
                   '<div class="ocp-summary-sub">What the numbers say about this community</div>' +
                   '<div id="ocp-ai-summary" class="ocp-ai-summary">' +
                     '<i class="fa fa-spinner fa-spin"></i> Reading the profile…' +
                   '</div>' +
                 '</div>' +
                 boundaryCard +
               '</div>';
    },

    _loadSummary: function(number) {
        var me = this;
        var seq = ++this._summarySeq;
        var seg = (number == null) ? 'chicago' : number;
        $.ajax({
            url: this._endpoint() + '/geography/community-areas/' + seg + '/profile/summary',
            type: 'GET',
            headers: this._authHeaders(),
            timeout: 45000,
            success: function(data) {
                if (seq !== me._summarySeq) { return; }
                $('#ocp-ai-summary').html(me._summaryHtml((data && data.summary) || 'Summary unavailable.'));
            },
            error: function() {
                if (seq !== me._summarySeq) { return; }
                $('#ocp-ai-summary').html('Summary unavailable right now.');
            }
        });
    },

    _renderBoundaryMap: function(geometry) {
        var el = document.getElementById('ocp-boundary-map');
        if (!el || !geometry || !window.L) {
            if (el) { el.innerHTML = '<div class="ocp-boundary-empty">No outline</div>'; }
            return;
        }

        this._destroyMiniMap();
        var map = L.map(el, {
            zoomControl: false,
            attributionControl: false,
            dragging: false,
            scrollWheelZoom: false,
            doubleClickZoom: false,
            boxZoom: false,
            keyboard: false,
            touchZoom: false,
            tap: false
        });
        this._miniMap = map;

        var base = ((ogrid.Config.map || {}).baseLayers || [])[0];
        if (base && base.url) {
            L.tileLayer(base.url, $.extend({}, base.options || {}, {
                attribution: '',
                opacity: 0.82
            })).addTo(map);
        }

        var layer = L.geoJson({ type: 'Feature', geometry: geometry }, {
            style: {
                color: '#2f77be',
                weight: 3,
                opacity: 1,
                fillColor: '#2f77be',
                fillOpacity: 0.18
            },
            interactive: false
        }).addTo(map);

        try {
            map.fitBounds(layer.getBounds(), { padding: [18, 18], animate: false });
        } catch (e) {
            map.setView([41.8781, -87.6298], 10);
        }
        setTimeout(function() {
            try { map.invalidateSize(false); } catch (e) {}
        }, 0);
    },

    _summaryHtml: function(text) {
        var parts = String(text || '').split(/\n+/).map(function(p) {
            return $.trim(p);
        }).filter(Boolean);
        if (!parts.length) {
            return 'Summary unavailable.';
        }
        return parts.map(function(p) {
            return '<p>' + this._esc(p) + '</p>';
        }, this).join('');
    },

    // --- Sectioned report (Demographics / Economics / ...) ----------------- #
    _renderSections: function(sections) {
        var me = this;
        this._pendingCharts = [];
        if (!sections || !sections.length) { return ''; }
        return sections.map(function(sec) {
            var groups = sec.groups.map(function(grp) {
                var items = grp.items.map(function(it) { return me._renderItem(it); }).join('');
                var title = grp.title ? '<div class="ocp-group-title">' + grp.title + '</div>' : '';
                return '<div class="ocp-group">' +
                         title +
                         '<div class="ocp-group-items">' + items + '</div>' +
                       '</div>';
            }).join('');
            return '<div class="ocp-section">' +
                     '<div class="ocp-section-rail"><span>' + sec.title + '</span></div>' +
                     '<div class="ocp-section-content">' + groups + '</div>' +
                   '</div>';
        }).join('');
    },

    _renderItem: function(it) {
        switch (it.type) {
            case 'stat':
                return this._statBlock(it.label, it.value, it.format, it.unit);
            case 'stat_list':
                return it.items.map(function(s) {
                    return this._statBlock(s.label, s.value, s.format, s.unit);
                }, this).join('');
            case 'pie':
                return this._chartBlock(it.label, 'pie', { slices: it.slices });
            case 'histogram':
            case 'column':
                return this._chartBlock(it.label, it.type,
                    { bins: it.bins, percent: (it.type === 'histogram') });
            case 'grouped_column':
                return this._chartBlock(it.label, 'grouped',
                    { categories: it.categories, series: it.series });
            case 'stacked_column':
                return this._chartBlock(it.label, 'stacked',
                    { segments: it.segments });
            case 'line':
                return this._chartBlock(it.label, 'line',
                    { points: it.points, format: it.format });
            case 'box_whisker':
                return this._chartBlock(it.label, 'boxWhisker',
                    { value: it.value, distribution: it.distribution, format: it.format });
            default:
                return '';
        }
    },

    _statBlock: function(label, value, fmt, unit) {
        var v = this._format(value, fmt);
        var u = unit ? ' <span class="ocp-stat-unit">' + unit + '</span>' : '';
        return '<div class="ocp-item ocp-stat">' +
                 '<div class="ocp-stat-value">' + v + u + '</div>' +
                 '<div class="ocp-stat-label">' + label + '</div>' +
               '</div>';
    },

    _chartBlock: function(label, kind, data) {
        var id = 'ocp-chart-' + (++this._chartSeq);
        this._pendingCharts.push({ id: id, kind: kind, data: data });
        return '<div class="ocp-item ocp-chart">' +
                 '<div class="ocp-item-label">' + label + '</div>' +
                 '<div class="ocp-canvas-wrap"><canvas id="' + id + '"></canvas></div>' +
               '</div>';
    },

    _instantiateCharts: function() {
        var me = this;
        (this._pendingCharts || []).forEach(function(spec) {
            var canvas = document.getElementById(spec.id);
            if (!canvas || !window.Chart || !ogrid.ProfileCharts) { return; }
            var chart = null;
            try {
                if (spec.kind === 'pie') {
                    chart = ogrid.ProfileCharts.pie(canvas, spec.data.slices);
                } else if (spec.kind === 'grouped') {
                    chart = ogrid.ProfileCharts.groupedBars(canvas, spec.data.categories, spec.data.series);
                } else if (spec.kind === 'stacked') {
                    chart = ogrid.ProfileCharts.stackedColumn(canvas, spec.data.segments);
                } else if (spec.kind === 'line') {
                    chart = ogrid.ProfileCharts.line(canvas, spec.data.points, { format: spec.data.format });
                } else if (spec.kind === 'boxWhisker') {
                    chart = ogrid.ProfileCharts.boxWhisker(canvas, spec.data);
                } else {
                    chart = ogrid.ProfileCharts.bars(canvas, spec.data.bins, { percent: spec.data.percent });
                }
            } catch (e) { /* skip a chart that fails to build */ }
            if (chart) { me._charts.push(chart); }
        });
        this._pendingCharts = [];
    },

    _destroyCharts: function() {
        (this._charts || []).forEach(function(c) { try { c.destroy(); } catch (e) {} });
        this._charts = [];
    },

    _destroyMiniMap: function() {
        if (this._miniMap) {
            try { this._miniMap.remove(); } catch (e) {}
            this._miniMap = null;
        }
    },

    _renderKpis: function(kpis) {
        var me = this;
        if (!kpis || !kpis.length) { return ''; }
        var cards = kpis.map(function(k) {
            var value = me._format(k.value, k.format);
            var context = (k.citywide != null)
                ? '<div class="ocp-kpi-context">Chicago: ' + me._format(k.citywide, k.format) + '</div>'
                : '';
            return (
                '<div class="ocp-kpi-card">' +
                  '<div class="ocp-kpi-label">' + k.label + '</div>' +
                  '<div class="ocp-kpi-value">' + value + '</div>' +
                  context +
                '</div>'
            );
        }).join('');
        return '<div class="ocp-kpi-grid">' + cards + '</div>';
    },

    _format: function(value, fmt) {
        if (value == null) { return '—'; }
        switch (fmt) {
            case 'currency':
                return '$' + Math.round(value).toLocaleString();
            case 'percent':
                return Math.round(value) + '%';
            case 'decimal':
                return (Math.round(value * 10) / 10).toFixed(1);
            case 'count':
                if (value >= 10000) { return (Math.round(value / 100) / 10) + 'k'; }
                return Math.round(value).toLocaleString();
            default:
                return String(value);
        }
    },

    _esc: function(value) {
        return String(value == null ? '' : value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }
});

// Lazily-created singleton so map-label clicks and the sidebar share one instance.
ogrid._communityProfile = null;
ogrid.communityProfile = function() {
    if (!ogrid._communityProfile) {
        ogrid._communityProfile = new ogrid.CommunityProfile();
    }
    return ogrid._communityProfile;
};


/* === src/js/custom/community/ProfileCharts.js === */
/*
 * ogrid.ProfileCharts
 *
 * Thin Chart.js 2.4.0 helpers for the Community Profile page: doughnut/pie, bar
 * (histogram / column), and grouped bar. Each returns a Chart instance so the caller
 * can destroy() it before re-rendering. Uses a fixed teal palette to match the design.
 *
 * Chart.js and chroma are already global (lib bundle). All value labels are drawn
 * defensively (try/catch) so a label-drawing hiccup never blanks the chart.
 */
ogrid.ProfileCharts = (function () {

    var TEAL = '#4f9c95';
    var SALMON = '#e3a597';
    // Teal-centric categorical palette for multi-slice pies / column charts.
    var PALETTE = ['#4f9c95', '#e3a597', '#7fbfb7', '#cf9a6e', '#2e6e68',
                   '#9cc7c2', '#c97f72', '#bcd6d2', '#6a928d', '#e8c9a0'];

    function color(i) { return PALETTE[i % PALETTE.length]; }

    function pctOf(value, total) {
        if (!total) { return 0; }
        return Math.round(value / total * 100);
    }

    // ---- Doughnut / pie --------------------------------------------------- #
    function pie(canvas, slices) {
        var total = slices.reduce(function (s, x) { return s + (x.value || 0); }, 0);
        var labels = slices.map(function (x) { return x.label + ' ' + pctOf(x.value, total) + '%'; });
        var colors = slices.map(function (x, i) { return color(i); });

        // Largest slice → center label (mirrors the mock's big % in the hole).
        var top = slices.reduce(function (a, b) { return (b.value > a.value) ? b : a; }, slices[0] || {});
        var centerPct = pctOf(top.value || 0, total);
        var centerLabel = top.label || '';

        return new Chart(canvas.getContext('2d'), {
            type: 'doughnut',
            data: {
                labels: labels,
                datasets: [{ data: slices.map(function (x) { return x.value; }),
                             backgroundColor: colors, borderColor: '#fff', borderWidth: 2 }]
            },
            options: {
                responsive: true, maintainAspectRatio: false, cutoutPercentage: 62,
                legend: { position: 'right', labels: { boxWidth: 12, fontSize: 11, padding: 8 } },
                tooltips: { callbacks: { label: function (item, data) {
                    var v = data.datasets[0].data[item.index];
                    return data.labels[item.index].replace(/ \d+%$/, '') +
                           ': ' + v.toLocaleString() + ' (' + pctOf(v, total) + '%)';
                } } },
                animation: { onComplete: function () {
                    try {
                        var ch = this.chart, ctx = ch.ctx;
                        var cx = (ch.chartArea.left + ch.chartArea.right) / 2;
                        var cy = (ch.chartArea.top + ch.chartArea.bottom) / 2;
                        ctx.save();
                        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
                        ctx.fillStyle = '#2c3e50';
                        ctx.font = '700 18px Helvetica, Arial, sans-serif';
                        ctx.fillText(centerPct + '%', cx, cy - 4);
                        ctx.fillStyle = '#6b7785';
                        ctx.font = '600 10px Helvetica, Arial, sans-serif';
                        ctx.fillText(centerLabel, cx, cy + 13);
                        ctx.restore();
                    } catch (e) { /* center label is decorative */ }
                } }
            }
        });
    }

    // ---- Bar (histogram / column) ---------------------------------------- #
    // opts.percent → label bars with their share of the total; else raw counts.
    function bars(canvas, bins, opts) {
        opts = opts || {};
        var total = bins.reduce(function (s, x) { return s + (x.value || 0); }, 0);
        var labelText = bins.map(function (x) {
            return opts.percent ? (pctOf(x.value, total) + '%') : shortNum(x.value);
        });

        return new Chart(canvas.getContext('2d'), {
            type: 'bar',
            data: {
                labels: bins.map(function (x) { return x.label; }),
                datasets: [{ data: bins.map(function (x) { return x.value; }),
                             backgroundColor: TEAL, borderWidth: 0, maxBarThickness: 64 }]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                legend: { display: false },
                tooltips: { callbacks: { label: function (item) {
                    return item.yLabel.toLocaleString() + ' (' + pctOf(item.yLabel, total) + '%)';
                } } },
                scales: {
                    xAxes: [{ gridLines: { display: false },
                              ticks: { fontSize: 10, fontColor: '#6b7785', maxRotation: 40, minRotation: 0 } }],
                    yAxes: [{ display: false, ticks: { beginAtZero: true } }]
                },
                layout: { padding: { top: 18 } },
                animation: { onComplete: function () { _drawBarLabels(this, labelText); } }
            }
        });
    }

    // ---- Grouped bar ------------------------------------------------------ #
    function groupedBars(canvas, categories, series) {
        return new Chart(canvas.getContext('2d'), {
            type: 'bar',
            data: {
                labels: categories,
                datasets: series.map(function (s, i) {
                    return { label: s.label, data: s.values,
                             backgroundColor: i === 0 ? TEAL : SALMON, borderWidth: 0, maxBarThickness: 40 };
                })
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                legend: { position: 'top', labels: { boxWidth: 12, fontSize: 11 } },
                tooltips: { callbacks: { label: function (item, data) {
                    return data.datasets[item.datasetIndex].label + ': ' + item.yLabel.toLocaleString();
                } } },
                scales: {
                    xAxes: [{ gridLines: { display: false }, ticks: { fontSize: 10, fontColor: '#6b7785' } }],
                    yAxes: [{ display: false, ticks: { beginAtZero: true } }]
                }
            }
        });
    }

    // ---- Stacked single-column bar --------------------------------------- #
    function stackedColumn(canvas, segments) {
        segments = segments || [];
        var total = segments.reduce(function (s, x) { return s + (x.value || 0); }, 0);

        return new Chart(canvas.getContext('2d'), {
            type: 'bar',
            data: {
                labels: ['Households'],
                datasets: segments.map(function (s, i) {
                    return { label: s.label, data: [s.value || 0],
                             backgroundColor: color(i), borderWidth: 0, maxBarThickness: 80 };
                })
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                legend: { position: 'right', labels: { boxWidth: 12, fontSize: 11, padding: 8 } },
                tooltips: { callbacks: { label: function (item, data) {
                    var ds = data.datasets[item.datasetIndex];
                    var v = ds.data[item.index] || 0;
                    return ds.label + ': ' + v.toLocaleString() + ' (' + pctOf(v, total) + '%)';
                } } },
                scales: {
                    xAxes: [{ stacked: true, gridLines: { display: false },
                              ticks: { fontSize: 10, fontColor: '#6b7785' } }],
                    yAxes: [{ stacked: true, display: false, ticks: { beginAtZero: true } }]
                }
            }
        });
    }

    // ---- Line chart ------------------------------------------------------- #
    function line(canvas, points, opts) {
        points = points || [];
        opts = opts || {};
        return new Chart(canvas.getContext('2d'), {
            type: 'line',
            data: {
                labels: points.map(function (x) { return x.label; }),
                datasets: [{
                    data: points.map(function (x) { return x.value || 0; }),
                    borderColor: TEAL,
                    backgroundColor: 'rgba(79, 156, 149, 0.14)',
                    borderWidth: 2,
                    pointBackgroundColor: TEAL,
                    pointBorderColor: '#fff',
                    pointBorderWidth: 1,
                    pointRadius: 3,
                    lineTension: 0.25,
                    fill: true
                }]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                legend: { display: false },
                tooltips: { callbacks: { label: function (item) {
                    return formatValue(item.yLabel, opts.format);
                } } },
                scales: {
                    xAxes: [{ gridLines: { display: false },
                              ticks: { fontSize: 10, fontColor: '#6b7785', maxRotation: 40, minRotation: 0 } }],
                    yAxes: [{ gridLines: { color: 'rgba(107,119,133,0.16)' },
                              ticks: { beginAtZero: true, callback: function(v) { return shortNum(v); },
                                       fontSize: 10, fontColor: '#6b7785' } }]
                },
                layout: { padding: { top: 8, right: 8, bottom: 0, left: 0 } }
            }
        });
    }

    // ---- Box-and-whisker comparison -------------------------------------- #
    function boxWhisker(canvas, spec) {
        spec = spec || {};
        var d = spec.distribution || {};
        var value = spec.value;
        var min = d.min, q1 = d.q1, median = d.median, q3 = d.q3, max = d.max, mean = d.mean;
        var ctx = canvas.getContext('2d');
        var parent = canvas.parentNode;
        var dpr = window.devicePixelRatio || 1;
        var cssW = Math.max(parent ? parent.clientWidth : 320, 280);
        var cssH = Math.max(parent ? parent.clientHeight : 180, 160);

        canvas.width = cssW * dpr;
        canvas.height = cssH * dpr;
        canvas.style.width = cssW + 'px';
        canvas.style.height = cssH + 'px';
        ctx.scale(dpr, dpr);

        function fmt(v) { return formatValue(v, spec.format); }
        function x(v) {
            if (v == null || max === min) { return 0; }
            return left + ((v - min) / (max - min)) * (right - left);
        }

        var left = 46, right = cssW - 26;
        var cy = Math.round(cssH * 0.48);
        var boxTop = cy - 28, boxH = 42;

        ctx.clearRect(0, 0, cssW, cssH);
        ctx.font = '600 11px Helvetica, Arial, sans-serif';
        ctx.fillStyle = '#6b7785';
        ctx.textAlign = 'center';

        if ([min, q1, median, q3, max].some(function(v) { return v == null; })) {
            ctx.fillText('Hardship Index unavailable', cssW / 2, cy);
            return { destroy: function() {} };
        }

        ctx.strokeStyle = '#9cc7c2';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x(min), cy);
        ctx.lineTo(x(max), cy);
        ctx.stroke();

        [min, max].forEach(function(v) {
            ctx.beginPath();
            ctx.moveTo(x(v), cy - 18);
            ctx.lineTo(x(v), cy + 18);
            ctx.stroke();
        });

        ctx.fillStyle = 'rgba(79, 156, 149, 0.2)';
        ctx.strokeStyle = TEAL;
        ctx.lineWidth = 2;
        ctx.fillRect(x(q1), boxTop, Math.max(x(q3) - x(q1), 2), boxH);
        ctx.strokeRect(x(q1), boxTop, Math.max(x(q3) - x(q1), 2), boxH);

        ctx.strokeStyle = '#2e6e68';
        ctx.beginPath();
        ctx.moveTo(x(median), boxTop - 6);
        ctx.lineTo(x(median), boxTop + boxH + 6);
        ctx.stroke();

        if (mean != null) {
            ctx.fillStyle = SALMON;
            ctx.beginPath();
            ctx.arc(x(mean), cy, 5, 0, Math.PI * 2);
            ctx.fill();
        }

        if (value != null) {
            var vx = x(value);
            ctx.strokeStyle = '#c97f72';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(vx, boxTop - 16);
            ctx.lineTo(vx, boxTop + boxH + 16);
            ctx.stroke();
            ctx.fillStyle = '#2c3e50';
            ctx.font = '700 12px Helvetica, Arial, sans-serif';
            ctx.fillText('This area: ' + fmt(value), vx, boxTop - 22);
        }

        ctx.fillStyle = '#6b7785';
        ctx.font = '600 10px Helvetica, Arial, sans-serif';
        ctx.fillText(fmt(min), x(min), cssH - 28);
        ctx.fillText(fmt(max), x(max), cssH - 28);
        ctx.fillText('Median ' + fmt(median), x(median), cssH - 10);
        if (mean != null) { ctx.fillText('Avg ' + fmt(mean), x(mean), cy + 34); }

        return { destroy: function() { ctx.clearRect(0, 0, canvas.width, canvas.height); } };
    }

    // Draw a small label above each bar of a single-dataset bar chart.
    function _drawBarLabels(chart, labelText) {
        try {
            var ctx = chart.chart.ctx;
            ctx.save();
            ctx.font = '600 10px Helvetica, Arial, sans-serif';
            ctx.fillStyle = '#6b7785'; ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
            var meta = chart.getDatasetMeta(0);
            meta.data.forEach(function (bar, i) {
                if (labelText[i] != null) { ctx.fillText(labelText[i], bar._model.x, bar._model.y - 2); }
            });
            ctx.restore();
        } catch (e) { /* bar labels are decorative */ }
    }

    function shortNum(v) {
        if (v == null) { return ''; }
        if (v >= 1000000) { return (Math.round(v / 100000) / 10) + 'M'; }
        if (v >= 10000) { return (Math.round(v / 100) / 10) + 'k'; }
        return Math.round(v).toLocaleString();
    }

    function formatValue(v, fmt) {
        if (v == null) { return ''; }
        if (fmt === 'currency') { return '$' + Math.round(v).toLocaleString(); }
        if (fmt === 'percent') { return Math.round(v) + '%'; }
        return Math.round(v).toLocaleString();
    }

    return { pie: pie, bars: bars, groupedBars: groupedBars,
             stackedColumn: stackedColumn, line: line, boxWhisker: boxWhisker, TEAL: TEAL };
})();


/* === src/js/custom/events/AnnouncementsPage.js === */
/*
 * AnnouncementsPage — full-page feed for announcements and events.
 *
 * First source: Chicago Public Library Events from City of Chicago Socrata.
 */
(function () {
    var _instance = null;

    function _esc(v) {
        return String(v == null ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    function _dateValue(d) {
        if (!d) { return ''; }
        return d.toISOString().slice(0, 10);
    }

    function _fmtDateTime(value) {
        if (!value) { return 'Time TBD'; }
        var d = new Date(value);
        if (isNaN(d.getTime())) { return value; }
        return d.toLocaleString([], {
            weekday: 'short',
            month: 'short',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit'
        });
    }

    function _fmtDate(value) {
        if (!value) { return ''; }
        var d = new Date(value);
        if (isNaN(d.getTime())) { return value; }
        return d.toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' });
    }

    function _fmtTime(value) {
        if (!value) { return ''; }
        var d = new Date(value);
        if (isNaN(d.getTime())) { return value; }
        return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    }

    function _fmtRange(event) {
        if (!event || !event.start) { return 'Time TBD'; }
        var start = _fmtDateTime(event.start);
        if (!event.end) { return start; }
        var s = new Date(event.start);
        var e = new Date(event.end);
        if (isNaN(s.getTime()) || isNaN(e.getTime())) {
            return start + ' - ' + event.end;
        }
        if (s.toDateString() === e.toDateString()) {
            return _fmtDate(event.start) + ' · ' + _fmtTime(event.start) + ' - ' + _fmtTime(event.end);
        }
        return start + ' - ' + _fmtDateTime(event.end);
    }

    function _chip(label) {
        if (!label) { return ''; }
        return '<span class="oae-chip"><i class="fa fa-circle-o"></i>' + _esc(label) + '</span>';
    }

    function _detailChip(kind, label) {
        if (!label) { return ''; }
        return '<span class="oae-affect-chip"><em>' + _esc(kind) + '</em>' + _esc(label) + '</span>';
    }

    function _eventHref(event) {
        return '#/announcements/' + encodeURIComponent(event.event_id || event.id || '');
    }

    function _externalLink(event) {
        return event.event_page_url
            ? '<a class="oae-card-link" href="' + _esc(event.event_page_url) + '" target="_blank" rel="noopener">Details</a>'
            : '';
    }

    function _card(event) {
        var desc = event.summary || event.description || '';
        var chips = [
            event.location_name,
            event.event_types,
            event.event_audiences,
            event.registration_status
        ].map(_chip).join('');
        var badge = event.badge || 'Event';
        var colored = !!event.badge_color;
        var badgeClass = colored ? 'oae-badge oae-badge-colored' : 'oae-badge';
        var badgeStyle = colored
            ? ' style="border-color:' + _esc(event.badge_color) + ';color:' + _esc(event.badge_color) + '"'
            : '';
        return '<article class="oae-card" id="event-' + _esc(event.event_id || event.id || '') + '" data-event-id="' + _esc(event.event_id || event.id || '') + '">' +
            '<div class="oae-card-top">' +
            '<span class="' + badgeClass + '"' + badgeStyle + '>' + _esc(badge) + '</span>' +
            '<time>' + _esc(_fmtDateTime(event.start)) + '</time>' +
            '</div>' +
            '<h3><a href="' + _eventHref(event) + '">' + _esc(event.title) + '</a></h3>' +
            '<div class="oae-meta">' + _esc(event.location_name || 'Chicago Public Library') +
                (event.location_details ? ' &middot; ' + _esc(event.location_details) : '') +
                (event.location_address ? ' &middot; ' + _esc(event.location_address) : '') +
            '</div>' +
            '<p>' + _esc(desc) + '</p>' +
            '<div class="oae-card-bottom"><div class="oae-chips">' + chips + '</div>' + _externalLink(event) + '</div>' +
            '</article>';
    }

    function _detailRow(label, value) {
        if (value == null || value === '') { return ''; }
        return '<div class="oae-detail-row"><span>' + _esc(label) + '</span><strong>' + _esc(value) + '</strong></div>';
    }

    function _eventLabelList(value) {
        if (!value) { return ''; }
        return String(value).split(';').map(function(v) { return v.trim(); }).filter(Boolean).join(', ');
    }

    ogrid.AnnouncementsPage = ogrid.Class.extend({
        _container: null,
        _events: [],
        _loaded: false,
        _source: 'all',
        _pendingEventId: null,
        _expandedFocusSearch: false,
        _timer: null,
        _detailMap: null,

        init: function(container) {
            this._container = $(container || '#ogrid-announcements-page');
            this._renderShell();
            this._bind();
        },

        show: function(options) {
            options = options || {};
            this._pendingEventId = options.eventId || null;
            this._expandedFocusSearch = false;
            this._container.removeClass('hide');
            if (this._pendingEventId) {
                this.load();
                return;
            }
            this._destroyDetailMap();
            this._renderShell();
            if (!this._loaded) {
                this.load();
            } else {
                this._renderEvents();
            }
        },

        hide: function() {
            this._destroyDetailMap();
            this._container.addClass('hide');
        },

        load: function() {
            var me = this;
            var params = this._params();

            // One unified endpoint merges every source (library, sports, Navy Pier,
            // Park District) server-side; detail lookups route by id prefix there too.
            if (this._pendingEventId) {
                this._renderDetailLoading();
                $.ajax({ url: this._base() + '/events/feed', data: params, timeout: 45000 })
                    .done(function(res) {
                        var selected = ((res && res.events) || [])[0];
                        if (selected) { me._renderDetail(selected); } else { me._renderDetailMissing(); }
                    })
                    .fail(function() { me._renderDetailError(); });
                return;
            }

            $('#oae-count').html('<i class="fa fa-spinner fa-spin"></i>');
            $('#oae-feed').html('<div class="oae-empty">Loading events...</div>');

            $.ajax({ url: this._base() + '/events/feed', data: params, timeout: 45000 })
                .done(function(res) {
                    me._loaded = true;
                    me._events = (res && res.events) || [];
                    me._renderEvents();
                })
                .fail(function() {
                    $('#oae-count').text('');
                    $('#oae-feed').html('<div class="oae-empty">Events are unavailable right now.</div>');
                });
        },

        // Combine sources into one chronologically-sorted feed (kept for compatibility).
        _mergeEvents: function(a, b) {
            var all = (a || []).concat(b || []);
            all.sort(function(x, y) {
                var xs = x.start || '', ys = y.start || '';
                return xs < ys ? -1 : (xs > ys ? 1 : 0);
            });
            return all;
        },

        _base: function() {
            return ogrid.Config.service.endpoint.replace(/\/rest\/?$/, '') + '/rest';
        },

        _params: function() {
            var params = { limit: 300 };
            var q = $('#oae-filter').val();
            var place = $('#oae-place').val();
            var neighborhood = $('#oae-neighborhood').val();
            var from = $('#oae-date-from').val();
            var to = $('#oae-date-to').val();
            if (this._pendingEventId) {
                params.event_id = this._pendingEventId;
                params.limit = 1;
                return params;
            }
            if (this._source && this._source !== 'all') { params.source = this._source; }
            if (q) { params.q = q; }
            if (place) { params.library = place; }
            if (neighborhood) { params.neighborhood = neighborhood; }
            if (from) { params.date_from = from + 'T00:00:00'; }
            if (to) { params.date_to = to + 'T23:59:59'; }
            return params;
        },

        _renderShell: function() {
            var today = new Date();
            var nextMonth = new Date(today.getTime());
            nextMonth.setDate(nextMonth.getDate() + 30);
            this._container.html(
                '<div class="oae-page">' +
                '<header class="oae-header">' +
                '<div class="oae-brand"><i class="fa fa-th-large"></i><span>OpenGrid</span></div>' +
                '<h1>Happening in Chicago</h1>' +
                '<div class="oae-filter-wrap"><i class="fa fa-search"></i><input id="oae-filter" type="text" placeholder="Filter this feed..."></div>' +
                '</header>' +
                '<div class="oae-toolbar">' +
                '<div class="oae-tabs">' +
                '<button type="button" class="' + (this._source === 'all' ? 'active' : '') + '" data-oae-source="all">All</button>' +
                '<button type="button" class="' + (this._source === 'library' ? 'active' : '') + '" data-oae-source="library">Library</button>' +
                '<button type="button" class="' + (this._source === 'sports' ? 'active' : '') + '" data-oae-source="sports">Sports</button>' +
                '<button type="button" class="' + (this._source === 'navypier' ? 'active' : '') + '" data-oae-source="navypier">Navy Pier</button>' +
                '<button type="button" class="' + (this._source === 'parkdistrict' ? 'active' : '') + '" data-oae-source="parkdistrict">Parks</button>' +
                '</div>' +
                '<div class="oae-controls">' +
                '<input id="oae-date-from" type="date" value="' + _dateValue(today) + '">' +
                '<input id="oae-date-to" type="date" value="' + _dateValue(nextMonth) + '">' +
                '<input id="oae-place" type="text" placeholder="Library">' +
                '<input id="oae-neighborhood" type="text" placeholder="Neighborhood">' +
                '<button id="oae-clear" type="button" title="Clear filters"><i class="fa fa-times"></i></button>' +
                '</div>' +
                '<div id="oae-count"></div>' +
                '</div>' +
                '<main id="oae-feed" class="oae-feed"></main>' +
                '</div>'
            );
        },

        _bind: function() {
            var me = this;
            this._container.on('input change', '#oae-filter,#oae-place,#oae-neighborhood,#oae-date-from,#oae-date-to', function() {
                me._pendingEventId = null;
                me._expandedFocusSearch = false;
                clearTimeout(me._timer);
                me._timer = setTimeout(function() { me.load(); }, 250);
            });
            this._container.on('click', '#oae-clear', function() {
                $('#oae-filter,#oae-place,#oae-neighborhood').val('');
                $('#oae-date-from,#oae-date-to').val('');
                me.load();
            });
            this._container.on('click', '.oae-tabs button', function() {
                me._source = $(this).data('oae-source') || 'all';
                $('.oae-tabs button').removeClass('active');
                $(this).addClass('active');
                me._pendingEventId = null;
                me._expandedFocusSearch = false;
                me.load();
            });
            this._container.on('click', '.oae-card h3 a', function(e) {
                e.preventDefault();
                e.stopPropagation();
                var id = $(this).closest('.oae-card').data('event-id');
                if (ogrid.App && ogrid.App.navigateToPage) {
                    ogrid.App.navigateToPage('announce', { eventId: id });
                }
            });
            this._container.on('click', '.oae-card', function(e) {
                if ($(e.target).closest('a,button').length) {
                    return;
                }
                e.preventDefault();
                var id = $(this).closest('.oae-card').data('event-id');
                if (ogrid.App && ogrid.App.navigateToPage) {
                    ogrid.App.navigateToPage('announce', { eventId: id });
                }
            });
            this._container.on('click', '#oae-back-to-feed', function() {
                if (ogrid.App && ogrid.App.navigateToPage) {
                    ogrid.App.navigateToPage('announce');
                }
            });
            this._container.on('click', '#oae-copy-link', function() {
                var url = window.location.href;
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(url);
                }
                $(this).text('Link copied');
            });
        },

        _renderEvents: function() {
            $('#oae-count').text(this._events.length.toLocaleString() + ' event' + (this._events.length === 1 ? '' : 's'));
            if (!this._events.length) {
                $('#oae-feed').html('<div class="oae-empty">No matching events.</div>');
                return;
            }
            $('#oae-feed').html(this._events.map(_card).join(''));
        },

        _renderDetailLoading: function() {
            this._destroyDetailMap();
            this._container.html(
                '<div class="oae-page oae-detail-page">' +
                '<header class="oae-detail-header">' +
                '<button id="oae-back-to-feed" type="button" class="oae-ghost-button"><i class="fa fa-arrow-left"></i> Back</button>' +
                '<div><div class="oae-detail-kicker"><span class="oae-badge">Event</span></div>' +
                '<h1>Loading event...</h1></div>' +
                '</header>' +
                '<main class="oae-detail-empty"><i class="fa fa-spinner fa-spin"></i> Loading event details...</main>' +
                '</div>'
            );
        },

        _renderDetailMissing: function() {
            this._destroyDetailMap();
            this._container.html(
                '<div class="oae-page oae-detail-page">' +
                '<header class="oae-detail-header">' +
                '<button id="oae-back-to-feed" type="button" class="oae-ghost-button"><i class="fa fa-arrow-left"></i> Back</button>' +
                '<div><div class="oae-detail-kicker"><span class="oae-badge">Event</span></div>' +
                '<h1>Event not found</h1></div>' +
                '</header>' +
                '<main class="oae-detail-empty">This event is not available in the current library events feed.</main>' +
                '</div>'
            );
        },

        _renderDetailError: function() {
            this._destroyDetailMap();
            this._container.html(
                '<div class="oae-page oae-detail-page">' +
                '<header class="oae-detail-header">' +
                '<button id="oae-back-to-feed" type="button" class="oae-ghost-button"><i class="fa fa-arrow-left"></i> Back</button>' +
                '<div><div class="oae-detail-kicker"><span class="oae-badge">Event</span></div>' +
                '<h1>Event unavailable</h1></div>' +
                '</header>' +
                '<main class="oae-detail-empty">Event details are unavailable right now.</main>' +
                '</div>'
            );
        },

        _renderDetail: function(event) {
            var me = this;
            var chips = [
                _detailChip('place', event.location_name || 'Chicago Public Library'),
                _detailChip('type', _eventLabelList(event.event_types)),
                _detailChip('audience', _eventLabelList(event.event_audiences)),
                _detailChip('zip', event.location_zip)
            ].join('');
            var description = event.description || event.summary || 'No event description is available.';
            var colored = !!event.badge_color;
            var detailBadge = event.badge || 'Civic Event';
            var detailBadgeClass = colored ? 'oae-badge oae-badge-colored' : 'oae-badge';
            var detailBadgeStyle = colored
                ? ' style="border-color:' + _esc(event.badge_color) + ';color:' + _esc(event.badge_color) + '"'
                : '';
            var sourceFeed = colored ? (event.source || 'Events') : 'Chicago Public Library Events';
            var sourceLink = event.event_page_url
                ? '<a class="oae-source-link" href="' + _esc(event.event_page_url) + '" target="_blank" rel="noopener">View original event <i class="fa fa-external-link"></i></a>'
                : '';

            this._destroyDetailMap();
            this._container.html(
                '<div class="oae-page oae-detail-page">' +
                '<header class="oae-detail-header">' +
                '<button id="oae-back-to-feed" type="button" class="oae-ghost-button"><i class="fa fa-arrow-left"></i> Back</button>' +
                '<div class="oae-detail-title-wrap">' +
                '<div class="oae-detail-kicker"><span class="' + detailBadgeClass + '"' + detailBadgeStyle + '>' + _esc(detailBadge) + '</span><span>' + _esc(_fmtRange(event)) + '</span></div>' +
                '<h1>' + _esc(event.title || 'Library Event') + '</h1>' +
                '</div>' +
                '<div class="oae-detail-actions">' +
                '<button id="oae-copy-link" type="button" class="oae-ghost-button"><i class="fa fa-link"></i> Copy link</button>' +
                '<button type="button" class="oae-primary-button"><i class="fa fa-bell"></i> Subscribe</button>' +
                '</div>' +
                '</header>' +
                '<main class="oae-detail-layout">' +
                '<section class="oae-detail-main">' +
                '<div class="oae-affects-label">Affects</div>' +
                '<div class="oae-affects">' + chips + '</div>' +
                '<article class="oae-detail-card">' +
                '<h2>Event Details</h2>' +
                '<p>' + _esc(description) + '</p>' +
                '<div class="oae-detail-rows">' +
                _detailRow('When', _fmtRange(event)) +
                _detailRow('Where', [event.location_name, event.location_details].filter(Boolean).join(' · ')) +
                _detailRow('Address', event.location_address) +
                _detailRow('Registration', event.registration_status || (event.registration_closed ? 'Closed' : '')) +
                _detailRow('Language', _eventLabelList(event.event_languages)) +
                _detailRow('Recurring', event.recurring ? 'Yes' : '') +
                '</div>' +
                '</article>' +
                '</section>' +
                '<aside class="oae-detail-side">' +
                '<div class="oae-location-card"><div id="oae-detail-map"></div><span>event location</span></div>' +
                '<article class="oae-source-card">' +
                '<div class="oae-source-label">Source · Provenance</div>' +
                '<h2>' + _esc(event.source || 'Chicago Public Library') + '</h2>' +
                '<div class="oae-source-muted">' + _esc(sourceFeed) + '</div>' +
                '<div class="oae-source-tags"><span>city data</span><span>source-linked</span></div>' +
                sourceLink +
                '</article>' +
                '</aside>' +
                '</main>' +
                '</div>'
            );
            window.setTimeout(function() { me._renderDetailMap(event); }, 40);
        },

        _destroyDetailMap: function() {
            if (this._detailMap) {
                try { this._detailMap.remove(); } catch (e) {}
                this._detailMap = null;
            }
        },

        _renderDetailMap: function(event) {
            var lat = Number(event && event.lat);
            var lon = Number(event && event.lon);
            var el = document.getElementById('oae-detail-map');
            if (!el || !window.L) { return; }
            if (isNaN(lat) || isNaN(lon)) {
                el.innerHTML = '<div class="oae-map-empty">No mapped location</div>';
                return;
            }
            this._destroyDetailMap();
            var map = L.map(el, {
                zoomControl: false,
                attributionControl: false,
                dragging: false,
                scrollWheelZoom: false,
                doubleClickZoom: false,
                boxZoom: false,
                keyboard: false,
                touchZoom: false,
                tap: false
            });
            this._detailMap = map;
            var base = ((ogrid.Config.map || {}).baseLayers || [])[0];
            if (base && base.url) {
                L.tileLayer(base.url, $.extend({}, base.options || {}, {
                    attribution: '',
                    opacity: 0.84
                })).addTo(map);
            }
            L.circleMarker([lat, lon], {
                radius: 8,
                color: '#c65f24',
                weight: 3,
                fillColor: '#c65f24',
                fillOpacity: 0.85
            }).addTo(map);
            map.setView([lat, lon], 15, { animate: false });
            map.invalidateSize(false);
        },

        _focusEvent: function(eventId) {
            var me = this;
            window.setTimeout(function() {
                var $card = $('#event-' + eventId);
                if (!$card.length) {
                    if (me._expandedFocusSearch) {
                        return;
                    }
                    me._expandedFocusSearch = true;
                    $('#oae-filter').val('');
                    $('#oae-place').val('');
                    $('#oae-neighborhood').val('');
                    $('#oae-date-from').val('');
                    $('#oae-date-to').val('');
                    me._pendingEventId = eventId;
                    me.load();
                    return;
                }
                $('.oae-card').removeClass('focused');
                $card.addClass('focused');
                $card[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 40);
        }
    });

    ogrid.announcementsPage = function() {
        if (!_instance) {
            _instance = new ogrid.AnnouncementsPage('#ogrid-announcements-page');
        }
        return _instance;
    };
}());


/* === src/js/custom/ext/leaflet-pdf.js === */
L.Control.Button = L.Control.extend({
    options: {
        position: 'topleft'
    },
    initialize: function (options) {
        this._button = {};
        this.setButton(options);
    },

    onAdd: function (map) {
        this._map = map;
        var container = L.DomUtil.create('div', 'leaflet-control-button');

        this._container = container;

        this._update();
        return this._container;
    },

    onRemove: function (map) {
    },

    setButton: function (options) {
        var button = {
            'text': options.text,                 //string
            'iconUrl': options.iconUrl,           //string
            'onClick': options.onClick,           //callback function
            'hideText': !!options.hideText,         //forced bool
            'maxWidth': options.maxWidth || 70,     //number
            'doToggle': options.toggle,			//bool
            'toggleStatus': false					//bool
        };

        this._button = button;
        this._update();
    },

    getText: function () {
        return this._button.text;
    },

    getIconUrl: function () {
        return this._button.iconUrl;
    },

    destroy: function () {
        this._button = {};
        this._update();
    },

    toggle: function (e) {
        if(typeof e === 'boolean'){
            this._button.toggleStatus = e;
        }
        else{
            this._button.toggleStatus = !this._button.toggleStatus;
        }
        this._update();
    },

    _update: function () {
        if (!this._map) {
            return;
        }

        this._container.innerHTML = '';
        this._makeButton(this._button);

    },

    _makeButton: function (button) {
        var newButton = L.DomUtil.create('div', 'leaflet-buttons-control-button', this._container);
        if(button.toggleStatus)
            L.DomUtil.addClass(newButton,'leaflet-buttons-control-toggleon');

        var image = L.DomUtil.create('img', 'leaflet-buttons-control-img', newButton);
        image.setAttribute('src',button.iconUrl);

        if(button.text !== ''){

            L.DomUtil.create('br','',newButton);  //there must be a better way

            var span = L.DomUtil.create('span', 'leaflet-buttons-control-text', newButton);
            var text = document.createTextNode(button.text);  //is there an L.DomUtil for this?
            span.appendChild(text);
            if(button.hideText)
                L.DomUtil.addClass(span,'leaflet-buttons-control-text-hide');
        }

        L.DomEvent
            .addListener(newButton, 'click', L.DomEvent.stop)
            .addListener(newButton, 'click', button.onClick,this)
            .addListener(newButton, 'click', this._clicked,this);
        L.DomEvent.disableClickPropagation(newButton);
        return newButton;

    },

    _clicked: function () {  //'this' refers to button
        if(this._button.doToggle){
            if(this._button.toggleStatus) {	//currently true, remove class
                L.DomUtil.removeClass(this._container.childNodes[0],'leaflet-buttons-control-toggleon');
            }
            else{
                L.DomUtil.addClass(this._container.childNodes[0],'leaflet-buttons-control-toggleon');
            }
            this.toggle();
        }
        return;
    }

});

