/* === src/js/ux/geofilter/GeoFilterFactory.js === */
/*
 * ogrid.GeoFilterFactory
 *
 * Factory class for getting appropriate geo filter object based on current settings
 */

ogrid.GeoFilterFactory = ogrid.Class.extend({
    //private attributes
    _options:{},

    //public attributes


    //constructor
    init: function(options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },

    //private methods


    //public methods
    getFilter: function(settings) {
        if (settings.boundaryType==='within') {
            switch(settings.boundary) {
                case '':
                    throw ogrid.error('Advanced Search', 'Invalid Within option \'' + settings.boundary + '\'');
                case '_map-extent':
                    return new ogrid.MapExtentGeoFilter(settings, this._options);

                case '_drawn-extent':
                    return new ogrid.DrawnGeoFilter(settings, this._options);
                default:
                    return new ogrid.ShapeGeoFilter(settings, this._options);
            }
        } else {
            //near
            if (settings.boundary === '_marker')
                return new ogrid.PointGeoFilter(settings, this._options);
            else if (settings.boundary === '_me') {
                return new ogrid.GeoLocationGeoFilter(settings, this._options);
            } else {
                throw ogrid.error('Advanced Search', 'Invalid Near option \'' + settings.boundary + '\'');
            }
        }

    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.geoFilterFactory = function (options) {
    return new ogrid.GeoFilterFactory(options);
};

/* === src/js/ux/geofilter/GeoLocationGeoFilter.js === */
/*
 * ogrid.PointGeoFilter
 *
 * Geo-filter processor based markers put on a map and max radius setting
 */


ogrid.GeoLocationGeoFilter = ogrid.BaseGeoFilter.extend({
    //private attributes
    _options:{},
    _settings: null,
    //public attributes


    //constructor
    init: function(settings, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
        this._settings = settings;
    },


    //private methods
    _getRadius: function() {
        if (!this._settings.maxRadius || !this._settings.maxRadiusUnit) {
            throw ogrid.error('Advanced Search (ogrid.PointGeoFilter)', 'Radius data is not initialized');
        }
        if (this._settings.maxRadiusUnit === 'miles')
            //convert to meters
            return (this._settings.maxRadius * 1609.34);
        else if (this._settings.maxRadiusUnit === 'feet')
            //convert to meters
            return (this._settings.maxRadius * 0.3048);
        throw ogrid.error('Advanced Search (ogrid.GeoLocationGeoFilter)', 'Unsupported radius unit \'' + this._settings.maxRadiusUnit  + '\'');
    },

    //public methods
    filter: function(data) {
        if (!this._settings.maxRadius || !this._settings.maxRadiusUnit) {
            throw ogrid.error('Advanced Search (ogrid.GeoLocationGeoFilter)', 'Radius data is not initialized');
        }

        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.GeoLocationGeoFilter)', 'No Geo-location coordinates were detected. Please allow geo-location detection in your browser.');
        }

        var filtered = [];

        var me = this;
        $.each(data.features, function( i, v ) {
            //check each data point against location LatLng + radius

            //shapeMap for Near Me will contain the LatLng of the last location found
            var c = L.circle(me._options.shapeMap, me._getRadius());
            //for debugging only
            //c.addTo(me._options.map);

            var b = c.getBounds();
            if (b.contains(L.latLng(v.geometry.coordinates[1], v.geometry.coordinates[0]))) {
                filtered.push(v);
            }
        });
        //create clone
        var o = $.extend(true, {}, data);
        o.features = filtered;
        return o;
    },

    getGeometry: function() {
        if (!this._settings.maxRadius || !this._settings.maxRadiusUnit) {
            throw ogrid.error('Advanced Search (ogrid.GeoLocationGeoFilter)', 'Radius data is not initialized');
        }

        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.GeoLocationGeoFilter)', 'No Geo-location coordinates were detected. Please allow geo-location detection in your browser.');
        }

        //shapeMap for Near Me will contain the LatLng of the last location found
        var c = L.circle(this._options.shapeMap, this._getRadius());

        //temp fix for Leaflet getBounds bug (https://github.com/Leaflet/Leaflet/issues/4978)
        this._fixCircleGetBounds(c);

        var coordinates = this._getCoordinatesFromLatLngBounds(c.getBounds());
        var polyGeo =  this._getEmptyPolygon();
        polyGeo.features[0].geometry.coordinates = coordinates;
        return polyGeo.features[0].geometry;
    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.geoLocationGeoFilter = function (settings, options) {
    return new ogrid.GeoLocationGeoFilter(options);
};

/* === src/js/ux/geofilter/MapExtentGeoFilter.js === */
/*
 * ogrid.MapExtentGeoFilter
 *
 * Geo-filter processor based on map extent
 */


ogrid.MapExtentGeoFilter = ogrid.BaseGeoFilter.extend({
    //private attributes
    _options:{},
    _settings: null,
    //public attributes


    //constructor
    init: function(settings, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
        this._settings = settings;
    },


    //private methods


    //public methods
    filter: function(data) {
        //filter is dynamic and extent is calculated in real-time
        if (!this._options.map) {
            throw ogrid.error('Advanced Search (ogrid.MapExtentGeoFilter)','Map object is not initialized');
        }
        var b = this._options.map.getBounds();
        var filtered = [];
        $.each(data.features, function( i, v ) {
            //test if in bounds
            if (b.contains(L.latLng(v.geometry.coordinates[1], v.geometry.coordinates[0])))
                filtered.push(v);
        });
        //create clone
        var o = $.extend(true, {}, data);
        o.features = filtered;
        return o;
    },

    getGeometry: function() {
        //filter is dynamic and extent is calculated in real-time
        if (!this._options.map) {
            throw ogrid.error('Advanced Search (ogrid.MapExtentGeoFilter)','Map object is not initialized');
        }
        var coordinates = this._getCoordinatesFromLatLngBounds(this._options.map.getBounds());
        var multiGeo =  this._getEmptyMultiPolygon();
        multiGeo.features[0].geometry.coordinates.push(coordinates);
        return multiGeo.features[0].geometry;
    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.mapExtentGeoFilter = function (settings, options) {
    return new ogrid.MapExtentGeoFilter(settings, options);
};

/* === src/js/ux/geofilter/PointGeoFilter.js === */
/*
 * ogrid.PointGeoFilter
 *
 * Geo-filter processor based markers put on a map and max radius setting
 */


ogrid.PointGeoFilter = ogrid.BaseGeoFilter.extend({
    //private attributes
    _options:{},
    _settings: null,
    //public attributes


    //constructor
    init: function(settings, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
        this._settings = settings;
    },


    //private methods
    _getRadius: function() {
        if (!this._settings.maxRadius || !this._settings.maxRadiusUnit) {
            throw ogrid.error('Advanced Search (ogrid.PointGeoFilter)', 'Radius data is not initialized');
        }
        if (this._settings.maxRadiusUnit === 'miles')
            //convert to meters
            return (this._settings.maxRadius * 1609.34);
        else if (this._settings.maxRadiusUnit === 'feet')
            //convert to meters
            return (this._settings.maxRadius * 0.3048);
        throw ogrid.error('Advanced Search (ogrid.PointGeoFilter)', 'Unsupported radius unit \'' + this._settings.maxRadiusUnit  + '\'');
    },

    //public methods
    filter: function(data) {
        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.PointGeoFilter)','Shape object is not initialized');
        }
        //shapeMap is of class L.featureGroup
        var filtered = [];

        var me = this;
        $.each(data.features, function( i, v ) {
            //check with each marker on the feature group
            $.each(me._options.shapeMap.getLayers(), function(j, w) {
                var c = L.circle(w.getLatLng(), me._getRadius());
                //for debugging only
                //c.addTo(me._options.map);

                var b = c.getBounds();
                if (b.contains(L.latLng(v.geometry.coordinates[1], v.geometry.coordinates[0]))) {
                    filtered.push(v);

                    //get out of each loop since this data point is already in our array
                    return false;
                }
            });
        });
        //create clone
        var o = $.extend(true, {}, data);
        o.features = filtered;
        return o;
    },

    getGeometry: function() {
        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.PointGeoFilter)','Shape object is not initialized');
        }
        var me = this;
        var multiGeo =  me._getEmptyMultiPolygon();
        $.each(me._options.shapeMap.getLayers(), function(i, v) {
            var c = L.circle(v.getLatLng(), me._getRadius());

            //temp fix for Leaflet getBounds bug (https://github.com/Leaflet/Leaflet/issues/4978)
            me._fixCircleGetBounds(c);

            var coordinates = me._getCoordinatesFromLatLngBounds(c.getBounds());
            multiGeo.features[0].geometry.coordinates.push(coordinates);
        });
        return multiGeo.features[0].geometry;
    }
});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.pointGeoFilter = function (settings, options) {
    return new ogrid.PointGeoFilter(options);
};

/* === src/js/ux/geofilter/ShapeGeoFilter.js === */
/*
 * ogrid.ShapeGeoFilter
 *
 * Geo-filter processor based markers geoJson shape objects, could end up with the same implementation as DrawnGeoFilter
 */


ogrid.ShapeGeoFilter = ogrid.BaseGeoFilter.extend({
    //private attributes
    _options:{},
    _settings: null,
    //public attributes


    //constructor
    init: function(settings, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
        this._settings = settings;
    },


    //private methods


    //public methods
    filter: function(data) {
        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.ShapeGeoFilter)','Shape object is not initialized');
        }

        //shapeMap is geoJson object
        var filtered = [];

        //value should have the value for boundary value
        if (this._options.shapeMap[this._settings.value]) {
            var layer = L.geoJson(this._options.shapeMap[this._settings.value]);
            $.each(data.features, function( i, v ) {
                //test if in layer
                var r = leafletPip.pointInLayer(L.latLng(v.geometry.coordinates[1], v.geometry.coordinates[0]), layer);
                if (r && (r.length > 0)) {
                    filtered.push(v);
                }
            });
        }

        //create clone
        var o = $.extend(true, {}, data);
        o.features = filtered;
        return o;
    },

    getGeometry: function() {
        if (!this._options.shapeMap) {
            throw ogrid.error('Advanced Search (ogrid.ShapeGeoFilter)','Shape object is not initialized');
        }
        if (this._options.shapeMap[this._settings.value]) {
            var me = this;
            var geoJSON = me._options.shapeMap[this._settings.value];
            var multiGeo =  me._getEmptyMultiPolygon();
            $.each(geoJSON.features, function( i, v ) {
                multiGeo.features[0].geometry.coordinates.push(v.geometry.coordinates);
            });
            return multiGeo.features[0].geometry;
        } else
            throw ogrid.error('Advanced Search (ogrid.ShapeGeoFilter)','Shape object is not initialized');

    }

});

//support syntax without 'new' keyword (note: Camel-cased name)
ogrid.shapeGeoFilter = function (settings, options) {
    return new ogrid.ShapeGeoFilter(settings, options);
};

/* === src/js/ux/manage/AdminUI.js === */
/*
 * ogrid.AdminUI
 *
 * UI for admin pages
 */


ogrid.AdminUI = ogrid.Class.extend({
    //private attributes
    _options:{
        datasets: null
    },
    _container: null,
    _groupAdmin: null,
    _userAdmin: null,

    //public attributes


    //constructor
    init: function(container, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
        this._container = container;

        //update DOM from template
        this._container.html(this._getTemplate());

        //stamp container with our class for our styles to work
        this._container.addClass('ogrid-admin-ui');

        this._groupAdmin = new ogrid.GroupAdmin($('#ogrid-manage-groups'),{
            postDelete: $.proxy(this._postGroupUpdate, this),
            postUpdate: $.proxy(this._postGroupUpdate, this),
            datasets: this._options.datasets
        });
        this._groupAdmin.refreshGroups();

        this._userAdmin = new ogrid.UserAdmin($('#ogrid-manage-users'));

        var me = this;

        $('.ogrid-admin-ui a[data-toggle="tab"]').on('shown.bs.tab', function (e) {
            //fix layout of tabs (height of table) switching tabs
            if ($(e.target).attr('href') === '#ogrid-manage-groups')
                me._groupAdmin.refreshLayout();
            else
                me._userAdmin.refreshLayout();
        });

        //subscribe to applicable opengrid client events
        ogrid.Event.on(ogrid.Event.types.CLEAR, $.proxy(this._onClear, this));
        ogrid.Event.on(ogrid.Event.types.LOGGED_IN, $.proxy(this._onLoggedIn, this));
    },

    _onLoggedIn: function(e) {
        //this._groupAdmin.refreshGroups();
        //this._groupAdmin.refreshDatasets();
        this._groupAdmin.initTable();
    },

    _onClear: function() {
        //set active tab to Build Query
        $('.ogrid-admin-ui a[href="#ogrid-manage-groups"]').tab('show');
    },

    _postGroupUpdate: function() {
        //refresh users panel when group is deleted
        this._userAdmin.refreshGroups();
    },


    _getTemplate: function() {
        //return static string so there is no additional external file dependency
        //  and to keep this widget more self-contained (may use an external file later if this becomes cumbersome)
        //we can use build-tools later to automate reading this from template to embedded string in our class
        return '<div id="ogrid-admin-ui-body" class="panel-body"><ul id="ogrid-adv-tabs" class="nav nav-tabs" role="tablist"><li class="active"><a  href="#ogrid-manage-groups" role="tab" data-toggle="tab">Manage Groups</a></li><li><a href="#ogrid-manage-users" role="tab" data-toggle="tab">Manage Users</a></li></ul><div id="ogrid-manage-content" class="tab-content"><div class="tab-pane active" id="ogrid-manage-groups"></div><div class="tab-pane" id="ogrid-manage-users"></div></div></div>';
    }


    //private methods


    //public methods

});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.adminUI = function (container, options) {
    return new ogrid.AdminUI(container, options);
};

