/*
 * ogrid.EntityAdmin
 *
 * Base class for admin UIs
 */

ogrid.EntityAdmin = ogrid.Class.extend({
    //private attributes
    _options:{},

    //public attributes


    //constructor
    init: function(container, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }
    },

    //private methods
    _commonErrorHandler: function (opName, err, rawErrorData, passThroughData) {
        //no use for pass through data right now (more used on success case)
        if (err && !$.isEmptyObject(err)) {
            ogrid.Alert.error(err.message + '(' + 'Code: ' + err.code + ')');
            //console.log(err.message + '(' + 'Code: ' + err.code + ')');
        } else {
            if (rawErrorData.txtStatus === 'timeout') {
                ogrid.Alert.error(opName + ' has timed out.');
                //console.log(opName + ' has timed out.');
            } else {
                ogrid.Alert.error( (rawErrorData.jqXHR.responseText) ? rawErrorData.jqXHR.responseText : rawErrorData.txtStatus);
                //console.log( (rawErrorData.jqXHR.responseText) ? rawErrorData.jqXHR.responseText : rawErrorData.txtStatus);
            }
        }
    }

    //public methods

});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.entityAdmin = function (options) {
    return new ogrid.EntityAdmin(options);
};

/* === src/js/ux/manage/GroupAdmin.js === */
/*
 * ogrid.GroupAdmin
 *
 * Group Admin UI class
 */

ogrid.GroupAdmin = ogrid.EntityAdmin.extend({
    //private attributes
    _options: {
        postDelete: null,
        postUpdate: null,
        datasets: null
    },
    _container: null,

    //public attributes


    //constructor
    init: function (container, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }

        this._container = container;

        //update DOM from template
        this._container.html(this._getTemplate());

        //stamp container with our class for our styles to work
        this._container.addClass('ogrid-manage-groups');

        this.initTable();

        this._modal = $('#group-edit-modal').modal({show: false});
        $('#ogrid-manage-group-modal-submit').click($.proxy(this._onModalSubmit, this));

    },


    //private methods
    _onModalSubmit: function () {
        var a = new ogrid.Admin('groups');

        //validate later

        if (this._modal.find('input[name="groupId"]').attr('readonly')) {
            //for update
            a.updateItem(this._modal.data('_id'), this._getGroup(), {
                success: $.proxy(this._onSaveSuccess, this),
                error: $.proxy(this._onSaveError, this)
            });
        } else {
            //new
            a.updateItem(null, this._getGroup(), {
                success: $.proxy(this._onSaveSuccess, this),
                error: $.proxy(this._onSaveError, this)
            });
        }
    },

    _getGroup: function () {
        return {
            groupId: this._modal.find('input[name="groupId"]').val(),
            name: this._modal.find('input[name="name"]').val(),
            description: this._modal.find('input[name="description"]').val(),
            enabled: this._modal.find('input[name="enabled"]').prop('checked'),
            isAdmin: this._modal.find('input[name="isAdmin"]').prop('checked'),
            functions: ( this._modal.data('functions') ? this._modal.data('functions') : [] ),
            datasets: ( this._modal.data('datasets') ? this._modal.data('datasets') : [] )
        };
    },

    _onSaveSuccess: function () {
        this._modal.modal('hide');

        //refresh list
        this.refreshGroups();
        if (this._options.postUpdate) {
            this._options.postUpdate();
        }
    },

    _onSaveError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('Group save', err, rawErrorData, passThroughData);
    },

    _onDeleteError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('Group delete', err, rawErrorData, passThroughData);
    },


    _getMultiPickerFormatter: function (title, name, options) {
        return function (value, row, index) {
            return '<div>' +
                '<select class="selectpicker" data-id="' + JSON.stringify(row._id) + '"' +
                ' data-selection="' + value + '"' +
                ' name="' + name + '"' +
                ' multiple title="' + title + '">' +
                $.map(options, function (v, i) {
                    return '<option>' + v + '</option>';
                }).join() +
                '</select>' +
                '</div>';
        };
    },

    _deleteItem: function (row) {
        ogrid.admin('groups').deleteItem(row._id, {
            success: $.proxy(this._onDeleteSuccess, this),
            error: $.proxy(this._onDeleteError, this)
        });
    },

    _onDeleteSuccess: function () {
        //refresh list
        this.refreshGroups();
        if (this._options.postDelete) {
            this._options.postDelete();
        }
    },

    initTable: function () {
        var me = this;

        var dataTypes = me._options.datasets;
        var accessFormatter = me._getMultiPickerFormatter(
            'Choose functions...',
            'functionsPicker',
            //sample UI security
            [ogrid.SecuredFunctions.ADVANCED_SEARCH, ogrid.SecuredFunctions.MANAGE]
        );

        var dataTypesFormatter = me._getMultiPickerFormatter(
            'Choose data types...',
            'dataTypesPicker',
            $.map(dataTypes, function (v, i) {
                return v.id;
            })
        );

        var viewFormatter = function (data, row, index) {
            return '<div>' +
                '<b>' + row.name + '</b><br>' +
                row.description +
                '</div>';
        };

        var actionFormatter = function (value) {
            return [
                '<a class="update" href="javascript:" title="Update Item"><i class="glyphicon glyphicon-edit"></i></a>',
                '<a class="remove" href="javascript:" title="Delete Item"><i class="glyphicon glyphicon-remove-circle"></i></a>',
            ].join('');
        };

        var actionEvents = {
            'click .update': function (e, value, row) {
                me._showModal($(this).attr('title'), 'groupId', 'name', row);
            },
            'click .remove': function (e, value, row) {
                ogrid.Alert.modalPrompt('Manage Groups', 'Are you sure you want to delete this group?', function (selected) {
                    //'ok' or 'cancel'
                    if (selected === 'ok') {
                        me._deleteItem(row);
                    }
                });
            }
        };

        var pickerEvents = {
            'change .selectpicker': function (e, value, row) {
                //var r = $.extend(true, {}, row);
                if ($(e.target).attr('title').indexOf('functions') > -1) {
                    row.functions = $(e.target).selectpicker('val');
                } else {
                    row.datasets = $(e.target).selectpicker('val');
                }
                ogrid.admin('groups').updateItem(row._id, row, {
                    success: $.proxy(this._onSaveSuccess, this),
                    error: $.proxy(this._onSaveError, this)
                });
            }
        };

        var cols = [
            {field: 'action', align: 'left', valign: 'middle', formatter: actionFormatter, events: actionEvents},
            {field: 'view', title: 'Group Details', formatter: viewFormatter},
            {field: '_id', title: 'Internal ID', visible: false},
            //{field: 'groupId', title: 'ID', visible: false},
            //{field: 'name', title: 'Name', visible: false},
            //{field: 'description', title: 'Description', visible: false},
            {field: 'functions', title: 'Functions', formatter: accessFormatter, events: pickerEvents},
            {field: 'datasets', title: 'Data Types', formatter: dataTypesFormatter, events: pickerEvents},
            //{field: 'enabled', title: 'Enabled', visible: false}
        ];

        $('#ogrid-table-groups').bootstrapTable({
            classes: 'table table-hover table-condensed',

            columns: cols,

            //TODO: make responsive later
            height: $(window).height() - 160,

            //pagination: true,
            toolbar: "#manage-group-toolbar"
        });
        $(window).resize(me._onWindowResize);
        $('.ogrid-manage-groups .create').click(function () {

            me._showModal($(this).text(), 'groupId');
        });
        me.refreshGroups();
    },

    _onWindowResize: function () {
        var options = $('#ogrid-table-groups').bootstrapTable('getOptions');
        $('#ogrid-table-groups').bootstrapTable('refreshOptions',
            $.extend(options, {height: $(window).height() - 160})
        );
        $('#ogrid-table-groups').bootstrapTable('resetView');
    },

    //input1 is the initial element to get focus if 'new'
    //input1 is the element to get focus if 'updating'
    _showModal: function (title, input1, input2, row) {
        var me = this;
        var r = row || {
                groupId: '',
                name: '',
                description: '',
                isAdmin: false,
                enabled: true
            }; // default row value

        //if update, disable ID
        if (row) {
            this._modal.find('input[name="' + input1 + '"]').attr('readonly', true);
            setTimeout(function () {
                me._modal.find('input[name="' + input2 + '"]').focus();
            }, 200);

            this._modal.data('functions', r.functions);
            this._modal.data('datasets', r.datasets);
        } else {
            var id = this._modal.find('input[name="' + input1 + '"]');
            id.removeAttr('readonly');
            setTimeout(function () {
                id.focus();
            }, 200);
            this._modal.data('functions', []);
            this._modal.data('datasets', []);
        }

        this._modal.data('_id', r._id);
        this._modal.find('.modal-title').text(title);
        for (var name in r) {
            var o = this._modal.find('input[name="' + name + '"]');
            if (o.attr('type') === 'checkbox') {
                o.prop('checked', r[name]);
            } else {
                o.val(r[name]);
            }
        }
        this._modal.modal('show');
    },


    _getTemplate: function () {
        //return static string so there is no additional external file dependency
        //  and to keep this widget more self-contained (may use an external file later if this becomes cumbersome)
        //we can use build-tools later to automate reading this from template to embedded string in our class
        return '<div id="manage-group-toolbar"><div class="form-inline" role="form"><div class="form-group"><button type="button" class="create btn btn-success">New group</button><!--<button type="button" class="btn btn-danger disabled">Delete group</button>--></div></div></div><table id="ogrid-table-groups"></table><div id="group-edit-modal" class="modal fade"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button><h4 class="modal-title"></h4></div><div class="modal-body"><div class="form-group"><label>ID</label><input type="text" class="form-control" name="groupId" placeholder="ID"></div><div class="form-group"><label>Name</label><input type="text" class="form-control" name="name" placeholder="Name"></div><div class="form-group"><label>Description</label><input type="text" class="form-control" name="description" placeholder="Description"></div><div class="checkbox"><label><input type="checkbox" name="isAdmin"> Is Admin Group</label></div><div class="checkbox"><label><input type="checkbox" name="enabled"> Enabled</label></div></div><div class="modal-footer"><button type="button" class="btn btn-default" data-dismiss="modal">Close</button><button id="ogrid-manage-group-modal-submit" type="button" class="btn btn-primary submit">Submit</button></div></div><!-- /.modal-content --></div><!-- /.modal-dialog --></div><!-- /.modal -->';
    },


    _onGroupListSuccess: function (data) {
        this.setData(data);
    },


    _onGroupListError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('Group listing', err, rawErrorData, passThroughData);
    },

    _getGroups: function () {
        ogrid.admin("groups").listItems({
            filter: {},
            maxResults: 200,
            success: $.proxy(this._onGroupListSuccess, this),
            error: $.proxy(this._onGroupListError, this)
        });
    },

    //public methods
    setData: function (data) {
        $('#ogrid-table-groups').bootstrapTable('load', data);
        $('#ogrid-table-groups select').each(function () {
            $(this).selectpicker();
            if ($(this).data('selection'))
                $(this).selectpicker('val', $(this).data('selection').split(','));
        });
        //force reset of layout
        this._onWindowResize();
    },

    refreshGroups: function () {
        this._getGroups();
    },

    refreshLayout: function () {
        this._onWindowResize();
    },

    refreshDatasets: function () {
        //get datasets
        var me = this;
        var dsCall = $.ajax(ogrid.Config.service.endpoint + '/datasets');
        dsCall.then(function (data) {
            $('#ogrid-table-groups select[name="dataTypesPicker"] ').each(function () {
                var val = $(this).selectpicker('val');
                $(this).find('option').remove();

                var me = this;
                $.each(data, function (i, v) {
                    $(me).append('<option>' + v.id + '</option>');
                });
                $(this).selectpicker('val', val);
                $(this).selectpicker('refresh');
            });
        });
    }
});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.groupAdmin = function (container, options) {
    return new ogrid.GroupAdmin(container, options);
};

/* === src/js/ux/manage/QueryAdmin.js === */
/*
 * ogrid.QueryAdmin
 *
 * QueryAdmin UI class for managing queries
 */

ogrid.QueryAdmin = ogrid.EntityAdmin.extend({
    //private attributes
    _options:{
        //event handler when play button is clicked
        //row data is passed
        onOpen: null,
        onPlay: null,
        postDelete: null
    },
    _container: null,
    _user: null,

    //public attributes


    //constructor
    init: function(container, currentUser, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }

        this._container = container;

        //update DOM from template
        this._container.html(this._getTemplate());

        //stamp container with our class for our styles to work
        this._container.addClass('ogrid-manage-queries');
        this._user = currentUser;

        this._initTable();
    },

    //private methods
     _deleteItem: function(row) {
        ogrid.admin('queries').deleteItem(row._id, {
            success: $.proxy(this._onSaveSuccess, this),
            error: $.proxy(this._onDeleteError, this)
        });
    },

    _onDeleteError:  function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('Query delete', err, rawErrorData, passThroughData);
    },

    _onSaveSuccess: function() {
        //refresh list
        this.refreshQueries();
        if (this._options.postDelete) {
            this._options.postDelete();
        }
    },


    _initTable: function() {
        var me = this;
        var actionFormatter = function(value, row) {
            var a = [];
            var isOwned = ((row.owner) === me._user.getProfile().loginId);

            a.push('<a class="play" href="#" title="Submit"><i class="glyphicon glyphicon-play-circle"></i></a>&nbsp');
            if (isOwned) {
                //can only share and delete if we're the owner
                a.push('<a class="share" href="#" title="Share"><i class="glyphicon glyphicon-share"></i></a>&nbsp');
                a.push('<a class="remove" href="#" title="Delete"><i class="glyphicon glyphicon-remove-circle"></i></a>');
            }
            return a.join('');
        };
        var actionEvents = {
            'click .play': function (e, value, row) {
                //me._showModal($(this).attr('title'), 'userId', 'password', row);
                if (me._options.onPlay) {
                    me._options.onPlay(row);
                }
            },
            'click .share': function (e, value, row) {
                alert('This feature is not yet implemented.');
            },
            'click .remove': function (e, value, row) {
                ogrid.Alert.modalPrompt('Manage Queries', 'Are you sure you want to delete this query?', function(selected) {
                    //'ok' or 'cancel'
                    if (selected === 'ok') {
                        me._deleteItem(row);
                    }
                });
            }
        };

        var nameFormatter = function(value, row, index) {
            //display 'Shared' icon if current user is not the owner of the query
            var sharedIcon = '<i class="fa fa-users" title="Shared with you or one of your groups by ' + row.owner + '"></i>';
            return '<a class="open" href="#" title="Open query">' +
                    value + '&nbsp' +
                    ( ((row.owner) !== me._user.getProfile().loginId) ? sharedIcon : '' ) +
                    '</a>';
        };

        var nameEvents = {
            'click .open': function (e, value, row) {
                //me._showModal($(this).attr('title'), 'userId', 'password', row);
                if (me._options.onOpen) {
                    me._options.onOpen(row);
                }
            }
        };

        var cols = [
            {field: '_id', title: 'Internal ID', visible: false},
            {field: 'name', title: 'Query Name', formatter: nameFormatter, events: nameEvents},
            {field: 'action', align: 'left', valign: 'center', formatter: actionFormatter, events: actionEvents},
        ];

        $('#ogrid-table-queries').bootstrapTable({
            classes: 'table table-hover table-condensed',
            columns: cols,

            //TODO: make responsive later
            height: $(window).height() - 160
            //pagination: true,
            //toolbar: "#manage-user-toolbar"
        });

        $(window).resize(this._onWindowResize);
     },

    _onWindowResize: function() {
        var options = $('#ogrid-table-queries').bootstrapTable('getOptions');
        $('#ogrid-table-queries').bootstrapTable('refreshOptions',
            $.extend(options, {height: $(window).height() - 160})
        );
        $('#ogrid-table-queries').bootstrapTable('resetView');
    },

    _getTemplate: function() {
        //return static string so there is no additional external file dependency
        //  and to keep this widget more self-contained (may use an external file later if this becomes cumbersome)
        //we can use build-tools later to automate reading this from template to embedded string in our class
        return '<table id="ogrid-table-queries"></table>';
    },


    _onQueriesListSuccess: function(data) {
        this.setData(data);
    },


    _onQueriesListError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('User listing', err, rawErrorData, passThroughData);
    },




    _getQueryFilter: function() {
        //queries that the logged in user owns or shared with him/his directly or with one of his groups

        return {
            $or: [
                {"owner": this._user.getProfile().loginId},
                {"sharedWith.users": {$in: [this._user.getProfile().loginId]}},
                //{"sharedWith.groups": { $in: ["opengrid_users","opengrid_users_L2"]} }
                {"sharedWith.groups": {$in: this._user.getProfile().roles }}
            ]
        };
    },

    _getQueries: function() {
        ogrid.admin("queries").listItems({
            filter: this._getQueryFilter(),
            maxResults: 500, //add to config later
            success: $.proxy(this._onQueriesListSuccess, this),
            error: $.proxy(this._onQueriesListSuccess, this)
        });
    },

    //public methods
    setData: function(data) {
        $('#ogrid-table-queries').bootstrapTable('load', data);
        $('#ogrid-table-queries').bootstrapTable('resetView');
    },

    refreshQueries: function() {
        this._getQueries();
    },


    setUser: function(user) {
        //leaves it to caller to refresh the list
        this._user = user;
    }
});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.queryAdmin = function (container, currentUserId, options) {
    return new ogrid.QueryAdmin(container,currentUserId,  options);
};

/* === src/js/ux/manage/UserAdmin.js === */
/*
 * ogrid.UserAdmin
 *
 * UserAdmin UI class
 */

ogrid.UserAdmin = ogrid.EntityAdmin.extend({
    //private attributes
    _options:{},
    _container: null,

    //public attributes


    //constructor
    init: function(container, options) {
        if (options) {
            this._options = ($.extend(this._options, options));
        }

        this._container = container;

        //update DOM from template
        this._container.html(this._getTemplate());

        //stamp container with our class for our styles to work
        this._container.addClass('ogrid-manage-users');

        this._initTable();

        this._modal = $('#user-edit-modal').modal({show: false});
        $('#ogrid-manage-user-modal-submit').click($.proxy(this._onModalSubmit, this));
    },



    //private methods
    _onModalSubmit: function() {
        var a = new ogrid.Admin('users');

        //validate later

        if (this._modal.find('input[name="userId"]').attr('readonly')) {
            //for update
            a.updateItem(this._modal.data('_id'), this._getUser(), {
                success: $.proxy(this._onSaveSuccess, this),
                error: $.proxy(this._onSaveError, this)
            });
        } else {
            //new
            a.updateItem(null, this._getUser(), {
                success: $.proxy(this._onSaveSuccess, this),
                error: $.proxy(this._onSaveError, this)
            });
        }
    },

    _getUser: function() {
        return {
            userId: this._modal.find('input[name="userId"]').val(),
            password: this._modal.find('input[name="password"]').val(),
            firstName:  this._modal.find('input[name="firstName"]').val(),
            lastName:  this._modal.find('input[name="lastName"]').val(),
            groups: ( this._modal.data('groups') ? this._modal.data('groups') : [] )
        };
    },

    _onSaveSuccess: function() {
        this._modal.modal('hide');

        //refresh list
        this.refreshUsers();
    },

    _onSaveError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('User save', err, rawErrorData, passThroughData);
    },


    _getMultiPickerFormatter: function(title, options) {
        return function(value, row, index) {
            return '<div>' +
                '<select class="selectpicker" data-id="' + JSON.stringify(row._id)  + '"' +
                ' data-selection="' + value  + '"' +
                ' multiple title="' + title + '">' +
                $.map(options, function(v, i) {
                    return '<option>' + v + '</option>';
                }).join() +
                '</select>' +
                '</div>';
        };
    },

    _deleteItem: function(row) {
        ogrid.admin('users').deleteItem(row._id, {
            success: $.proxy(this._onSaveSuccess, this),
            error: $.proxy(this._onDeleteError, this)
        });
    },

    _onDeleteError:  function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('User delete', err, rawErrorData, passThroughData);
    },


    _onGroupListError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('Group listing', err, rawErrorData, passThroughData);
    },

    _initTable: function() {
        //get groups
        ogrid.admin("groups").listItems({
            filter: {},
            maxResults: 200,
            success: $.proxy(this._initTableContinue,this),
            error: $.proxy(this._onGroupListError, this)
        });
    },

    _initTableContinue: function(groups) {
        var me = this;
        var a = $.map(groups, function(v, i) {
            return v.groupId;
        });
        var groupsFormatter = this._getMultiPickerFormatter(
            'Choose groups...',
            a
        );

        var actionFormatter = function(value) {
            return [
                '<a class="update" href="javascript:" title="Update Item"><i class="glyphicon glyphicon-edit"></i></a>',
                '<a class="remove" href="javascript:" title="Delete Item"><i class="glyphicon glyphicon-remove-circle"></i></a>',
            ].join('');
        };

        var actionEvents = {
            'click .update': function (e, value, row) {
                me._showModal($(this).attr('title'), 'userId', 'password', row);
            },
            'click .remove': function (e, value, row) {
                ogrid.Alert.modalPrompt('Manage Users', 'All queries saved by this users will deleted as well. Continue?', function(selected) {
                    //'ok' or 'cancel'
                    if (selected === 'ok') {
                        me._deleteItem(row);
                    }
                });
            }
        };

        var pickerEvents = {
            'change .selectpicker': function (e, value, row) {
                row.groups = $(e.target).selectpicker('val');
                ogrid.admin('users').updateItem(row._id, row, {
                    success: $.proxy(this._onSaveSuccess, this),
                    error: $.proxy(this._onSaveError, this)
                });
            }
        };

        var cols = [
            {field: 'action', align: 'left', valign: 'middle', formatter: actionFormatter, events: actionEvents, width: 50},
            {field: '_id', title: 'Internal ID', visible: false},
            {field: 'userId', title: 'User ID'},
            {field: 'firstName', title: 'First Name'},
            {field: 'lastName', title: 'Last Name'},
            {field: 'groups', title: 'Groups', formatter: groupsFormatter, events: pickerEvents}
        ];

        $('#ogrid-table-users').bootstrapTable({
            classes: 'table table-hover table-condensed',

            columns: cols,

            //TODO: make responsive later
            //height: $(window).height() - 160,
            //pagination: true,
            toolbar: "#manage-user-toolbar"
        });

        $(window).resize(this._onWindowResize);

        $('.ogrid-manage-users .create').click(function () {
            me._showModal($(this).text(), 'userId');
        });

        this.refreshUsers();
    },

    _onWindowResize: function() {
        var options = $('#ogrid-table-users').bootstrapTable('getOptions');
        $('#ogrid-table-users').bootstrapTable('refreshOptions',
            $.extend(options, {height: $(window).height() - 160})
        );
        $('#ogrid-table-users').bootstrapTable('resetView');
    },

    //input1 is the initial element to get focus if 'new'
    //input1 is the element to get focus if 'updating'
    _showModal: function(title, input1, input2, row) {
        var me = this;
        var r = row || {
                userId: '',
                password: '',
                firstName: '',
                lastName: ''
            }; // default row value

        //if update, disable ID
        if (row) {
            this._modal.find('input[name="' + input1 + '"]').attr('readonly', true);
            setTimeout(function() {
                me._modal.find('input[name="' + input2 + '"]').focus();
            }, 200);

            this._modal.data('groups', r.groups);
        } else {
            var id = this._modal.find('input[name="' + input1 + '"]');
            id.removeAttr('readonly');
            setTimeout(function() {
                id.focus();
            }, 200);
            this._modal.data('groups', []);
        }

        this._modal.data('_id', r._id);
        this._modal.find('.modal-title').text(title);
        for (var name in r) {
            var o = this._modal.find('input[name="' + name + '"]');
            if (o.attr('type') === 'checkbox') {
                o.prop('checked', r[name]);
            } else {
                o.val(r[name]);
            }
        }
        this._modal.modal('show');
    },


    _getTemplate: function() {
        //return static string so there is no additional external file dependency
        //  and to keep this widget more self-contained (may use an external file later if this becomes cumbersome)
        //we can use build-tools later to automate reading this from template to embedded string in our class
        return '<div id="manage-user-toolbar"><div class="form-inline" role="form"><div class="form-group"><button type="button" class="create btn btn-success">New user</button></div></div></div><table id="ogrid-table-users"></table><div id="user-edit-modal" class="modal fade"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button><h4 class="modal-title"></h4></div><div class="modal-body"><div class="form-group"><label>User ID</label><input type="text" class="form-control" name="userId" placeholder="User ID"></div><div class="form-group"><label>Password</label><input type="password" class="form-control" name="password" placeholder="Password"></div><div class="form-group"><label>First Name</label><input type="text" class="form-control" name="firstName" placeholder="First Name"></div><div class="form-group"><label>Last Name</label><input type="text" class="form-control" name="lastName" placeholder="Last Name"></div></div><div class="modal-footer"><button type="button" class="btn btn-default" data-dismiss="modal">Close</button><button id="ogrid-manage-user-modal-submit" type="button" class="btn btn-primary submit">Submit</button></div></div><!-- /.modal-content --></div><!-- /.modal-dialog --></div><!-- /.modal -->';
    },


    _onUserListSuccess: function(data) {
        this.setData(data);
    },

    _onUserListError: function (err, rawErrorData, passThroughData) {
        this._commonErrorHandler('User listing', err, rawErrorData, passThroughData);
    },

    _getUsers: function() {
        ogrid.admin("users").listItems({
            filter: {},
            maxResults: 1000,
            success: $.proxy(this._onUserListSuccess, this),
            error: $.proxy(this._onUserListError, this)
        });
    },

    //public methods
    setData: function(data) {
        $('#ogrid-table-users').bootstrapTable('load', data);
        $('#ogrid-table-users select').each(function () {
            $(this).selectpicker();
            if ($(this).data('selection'))
                $(this).selectpicker('val', $(this).data('selection').split(','));
        });

        //force reset of layout
        this._onWindowResize();
    },

    refreshUsers: function() {
        this._getUsers();
    },

    refreshGroups: function() {
        //get groups
        ogrid.admin("groups").listItems({
            filter: {},
            maxResults: 200,
            success: function(data) {
                $('#ogrid-table-users .selectpicker').each(function () {
                    var val = $(this).selectpicker('val');
                    $(this).find('option').remove();

                    var me = this;
                    $.each(data, function(i, v) {
                        $(me).append('<option>' + v.groupId + '</option>');
                    });
                    $(this).selectpicker('val', val);
                    $(this).selectpicker('refresh');
                });
            },
            error: $.proxy(this._onGroupListError, this)
        });
    },

    refreshLayout: function() {
        this._onWindowResize();
    }
});

//support syntax without 'new' keyword (note: camel-back name)
ogrid.userAdmin = function (container, options) {
    return new ogrid.UserAdmin(container, options);
};
